# -*- coding: utf-8 -*-
"""doi_chieu_khach.py - đối chiếu hình AI đã vẽ (file <đơn>_ALL.dxf hoặc file riêng) với DXF khách trong thư mục đơn.
Không cần AI: chạy local, 0 token. Chỉ BÁO chỗ khác, không sửa file.

Dùng:  py -X utf8 doi_chieu_khach.py <ALL.dxf | 26-xxxxxx.dxf> [--src THU_MUC_DON] [--code 068884,068885] [--json]
Mã thoát: 0 = không có cảnh báo, 1 = có cảnh báo, 2 = lỗi đọc file.

Cách làm: mở DXF khách (cả BLOCK/INSERT, POLYLINE), tìm phép đặt (8 hướng + tịnh tiến, tỉ lệ 1:1) cho hình AI chồng
khít nhất lên một hình chiếu của khách, rồi so:
  - lỗ: cùng tâm mà khác φ; AI lấy vòng ngoài của nhóm vòng đồng tâm (khoét đầu vít chìm/ザグリ, ký hiệu ren);
    lỗ mồi không đúng cỡ ren của ký hiệu ren DXF khách; lỗ lệch vị trí; lỗ khách có mà hình AI không có;
  - biên dạng: cạnh/cung của hình AI không nằm trên nét nào của DXF khách (kèm độ lệch);
  - hốc/rãnh/bậc không xuyên: hình chiếu cạnh của DXF khách (chữ nhật mỏng bằng chiều dày, cùng bề rộng hình phẳng) có nét ngang nằm giữa
    chiều dày mà hình AI vẽ cạnh/cung đúng đoạn đó -> CẢNH BÁO (phần không xuyên hết chiều dày không vẽ làm biên cắt); bỏ qua khoét đầu vít/ザグリ.
Chỗ khác mà mã đó không có Flag 1 ("Kích thước PDF và DXF khác nhau") thì báo CẢNH BÁO (thiếu Flag 1 hoặc vẽ sai).
Giới hạn: chi tiết uốn chỉ đối chiếu được cụm lỗ (hình trải không trùng hình chiếu); DXF khách vẽ khác tỉ lệ 1:1 thì bỏ qua;
không biết nét bị gạch tay trên PDF, không biết mặt ngoài/kegaki. Kết quả là gợi ý để xem lại, không phải kết luận.
"""
import argparse
import json
import math
import os
import re
import sys
import unicodedata
from collections import defaultdict

import ezdxf

TOL = 0.05            # sai số coi là trùng
CELL = 10.0
ORI = [
    ('giữ nguyên hướng', lambda x, y: (x, y)),
    ('xoay 180°', lambda x, y: (-x, -y)),
    ('xoay 90° ngược chiều kim đồng hồ', lambda x, y: (-y, x)),
    ('xoay 90° cùng chiều kim đồng hồ', lambda x, y: (y, -x)),
    ('lật trái-phải', lambda x, y: (-x, y)),
    ('lật trên-dưới', lambda x, y: (x, -y)),
    ('xoay 90° rồi lật', lambda x, y: (y, x)),
    ('xoay 270° rồi lật', lambda x, y: (-y, -x)),
]
# lỗ mồi taro theo cỡ ren (Quy_Tac_Lo_Moi.md); chỉ dùng để nhận ra ký hiệu ren, không thay bảng gốc
PILOT_D = {2: 1.6, 2.5: 2.1, 2.6: 2.2, 3: 2.5, 3.5: 2.9, 4: 3.3, 5: 4.2, 6: 5.0, 7: 6.0, 8: 6.8, 10: 8.5, 12: 10.3, 14: 12.0, 16: 14.0}
FLAG1 = 'Kích thước PDF và DXF khác nhau'
FLAG18 = 'Kích thước có dung sai'


def f(v):
    return ('%.3f' % v).rstrip('0').rstrip('.')


def decode_u(s):
    return unicodedata.normalize('NFC', re.sub(r'\\U\+([0-9A-Fa-f]{4})', lambda m: chr(int(m.group(1), 16)), s))


# ---------------------------------------------------------------- hình AI
def col_of(e):
    c = e.dxf.color if e.dxf.hasattr('color') else 256
    return 7 if c in (0, 7, 256) else c


def arc_pt(c, r, a):
    return (c[0] + r * math.cos(math.radians(a)), c[1] + r * math.sin(math.radians(a)))


def load_ai(path):
    """Trả về [(mã, [entity], [câu Flag])]. entity: ('L', p1, p2) | ('A', tâm, R, a0, quét) | ('C', tâm, R); chỉ nét cắt trắng."""
    doc = ezdxf.readfile(path)
    ents, codes, flags = [], [], []
    for e in doc.modelspace():
        t = e.dxftype()
        if t == 'TEXT':
            tx = e.dxf.text.strip()
            if re.fullmatch(r'\d{6}', tx):
                codes.append((e.dxf.insert.y, tx))
            elif col_of(e) == 6:
                flags.append((e.dxf.insert.y, decode_u(tx)))
            continue
        lt = (e.dxf.linetype if e.dxf.hasattr('linetype') else '').upper()
        if col_of(e) == 3 and lt != 'DASHED' and t in ('LINE', 'ARC'):
            if t == 'LINE':
                ents.append(('G', (e.dxf.start.x, e.dxf.start.y), (e.dxf.end.x, e.dxf.end.y)))   # rạch Green: chỉ để biết quanh góc có rạch hay không
            else:
                ents.append(('G', arc_pt((e.dxf.center.x, e.dxf.center.y), e.dxf.radius, e.dxf.start_angle), arc_pt((e.dxf.center.x, e.dxf.center.y), e.dxf.radius, e.dxf.end_angle)))
            continue
        if col_of(e) != 7 or lt == 'DASHED':
            if lt == 'DASHED' and t == 'LINE':
                ents.append(('B', (e.dxf.start.x, e.dxf.start.y), (e.dxf.end.x, e.dxf.end.y)))   # đường uốn: chỉ để biết chi tiết có uốn
            continue                      # đường uốn, kegaki, rạch Green: không có trong DXF khách theo cùng nghĩa
        if t == 'LINE':
            ents.append(('L', (e.dxf.start.x, e.dxf.start.y), (e.dxf.end.x, e.dxf.end.y)))
        elif t == 'CIRCLE':
            ents.append(('C', (e.dxf.center.x, e.dxf.center.y), e.dxf.radius))
        elif t == 'ARC':
            ents.append(('A', (e.dxf.center.x, e.dxf.center.y), e.dxf.radius, e.dxf.start_angle, (e.dxf.end_angle - e.dxf.start_angle) % 360))
    if not codes:
        m = re.search(r'(\d{6})', os.path.basename(path))
        return [(m.group(1) if m else os.path.basename(path), ents, None)]      # file riêng: không có Flag để xét

    def yr(e):
        if e[0] in ('L', 'B', 'G'):
            return min(e[1][1], e[2][1]), max(e[1][1], e[2][1])
        if e[0] == 'A':
            ys = [arc_pt(e[1], e[2], e[3] + e[4] * k / 8)[1] for k in range(9)]
            return min(ys), max(ys)
        return e[1][1] - e[2], e[1][1] + e[2]
    bands = []
    for y0, y1, e in sorted(((yr(e)[0], yr(e)[1], e) for e in ents), key=lambda z: z[0]):
        if bands and y0 <= bands[-1][1] + 100:
            bands[-1][1] = max(bands[-1][1], y1)
            bands[-1][2].append(e)
        else:
            bands.append([y0, y1, [e]])
    codes.sort(reverse=True)
    out = []
    for y0, y1, es in reversed(bands):
        cd = [c for y, c in codes if y0 - 1 <= y <= y1 + 1]
        if not cd:
            continue
        cy = next(y for y, c in codes if c == cd[0])
        nxt = max([y for y, c in codes if y < cy] or [-1e18])
        fl = ' '.join(t for y, t in sorted(flags, reverse=True) if nxt < y < cy)
        out.append((cd[0], es, [x.strip() for x in re.split(r'(?:^|\s)\d+\.\s', fl) if x.strip()]))
    return out


def tf_ent(e, fn, mirror):
    if e[0] == 'L':
        return ('L', fn(*e[1]), fn(*e[2]))
    if e[0] == 'C':
        return ('C', fn(*e[1]), e[2])
    c = fn(*e[1])
    p0, p1 = fn(*arc_pt(e[1], e[2], e[3])), fn(*arc_pt(e[1], e[2], e[3] + e[4]))
    if mirror:
        p0, p1 = p1, p0
    a0 = math.degrees(math.atan2(p0[1] - c[1], p0[0] - c[0]))
    return ('A', c, e[2], a0, e[4])


# ---------------------------------------------------------------- DXF khách
class Khach:
    def __init__(self, path):
        self.path = path
        self.lines, self.circ, self.arcs = [], [], []
        self.red = []                         # nét đỏ (màu 1) ngắn: chỗ khách chỉ rạch ở góc lõm
        self._walk(ezdxf.readfile(path).modelspace(), 0)
        self.grid = defaultdict(list)
        for i, (x1, y1, x2, y2) in enumerate(self.lines):
            n = max(1, int(math.hypot(x2 - x1, y2 - y1) / (CELL / 2)))
            seen = set()
            for k in range(n + 1):
                key = (int(math.floor((x1 + (x2 - x1) * k / n) / CELL)), int(math.floor((y1 + (y2 - y1) * k / n) / CELL)))
                if key not in seen:
                    seen.add(key)
                    self.grid[key].append(('L', i))
        for kind, lst in (('C', self.circ), ('A', self.arcs)):
            for i, it in enumerate(lst):
                cx, cy, r = it[0], it[1], it[2]
                n = max(8, int(2 * math.pi * r / (CELL / 2)))
                seen = set()
                for k in range(n):
                    a = 2 * math.pi * k / n
                    key = (int(math.floor((cx + r * math.cos(a)) / CELL)), int(math.floor((cy + r * math.sin(a)) / CELL)))
                    if key not in seen:
                        seen.add(key)
                        self.grid[key].append((kind, i))
        self.cgrid = defaultdict(list)       # tâm vòng tròn và cung nhỏ (ký hiệu ren)
        for cx, cy, r in self.circ:
            self.cgrid[(int(math.floor(cx)), int(math.floor(cy)))].append((cx, cy, r, 'C'))
        for cx, cy, r, a0, sw in self.arcs:
            if r <= 30 and sw >= 180:
                self.cgrid[(int(math.floor(cx)), int(math.floor(cy)))].append((cx, cy, r, 'A'))

    def _walk(self, ents, depth):
        for e in ents:
            t = e.dxftype()
            try:
                if t == 'INSERT' and depth < 5:
                    self._walk(e.virtual_entities(), depth + 1)
                elif t in ('LWPOLYLINE', 'POLYLINE'):
                    self._walk(e.virtual_entities(), depth + 1)
                elif t == 'LINE':
                    self.lines.append((e.dxf.start.x, e.dxf.start.y, e.dxf.end.x, e.dxf.end.y))
                    if e.dxf.color == 1 and 0.3 <= math.hypot(e.dxf.end.x - e.dxf.start.x, e.dxf.end.y - e.dxf.start.y) <= 3.0:
                        self.red.append((e.dxf.start.x, e.dxf.start.y, e.dxf.end.x, e.dxf.end.y))
                elif t == 'CIRCLE':
                    flip = e.dxf.extrusion.z < 0          # BLOCK chèn lật (extrusion -Z): toạ độ đang ở OCS, đổi về WCS
                    self.circ.append((-e.dxf.center.x if flip else e.dxf.center.x, e.dxf.center.y, e.dxf.radius))
                elif t == 'ARC':
                    sw = (e.dxf.end_angle - e.dxf.start_angle) % 360
                    if e.dxf.extrusion.z < 0:
                        self.arcs.append((-e.dxf.center.x, e.dxf.center.y, e.dxf.radius, (180 - e.dxf.end_angle) % 360, sw))
                    else:
                        self.arcs.append((e.dxf.center.x, e.dxf.center.y, e.dxf.radius, e.dxf.start_angle, sw))
            except Exception:
                continue

    def dist(self, p, lim=CELL):
        """khoảng cách từ điểm tới nét gần nhất (chỉ tìm trong lim)"""
        gx, gy = int(math.floor(p[0] / CELL)), int(math.floor(p[1] / CELL))
        best = lim
        seen = set()
        for ix in (gx - 1, gx, gx + 1):
            for iy in (gy - 1, gy, gy + 1):
                for it in self.grid.get((ix, iy), ()):
                    if it in seen:
                        continue
                    seen.add(it)
                    if it[0] == 'L':
                        x1, y1, x2, y2 = self.lines[it[1]]
                        dx, dy = x2 - x1, y2 - y1
                        L2 = dx * dx + dy * dy
                        t = 0 if L2 == 0 else max(0, min(1, ((p[0] - x1) * dx + (p[1] - y1) * dy) / L2))
                        d = math.hypot(p[0] - x1 - t * dx, p[1] - y1 - t * dy)
                    elif it[0] == 'C':
                        cx, cy, r = self.circ[it[1]]
                        d = abs(math.hypot(p[0] - cx, p[1] - cy) - r)
                    else:
                        cx, cy, r, a0, sw = self.arcs[it[1]]
                        ang = (math.degrees(math.atan2(p[1] - cy, p[0] - cx)) - a0) % 360
                        if ang <= sw + 0.5 or ang >= 359.5:
                            d = abs(math.hypot(p[0] - cx, p[1] - cy) - r)
                        else:
                            d = min(math.hypot(p[0] - q[0], p[1] - q[1]) for q in (arc_pt((cx, cy), r, a0), arc_pt((cx, cy), r, a0 + sw)))
                    if d < best:
                        best = d
        return best

    def profiles(self):
        """Hình chiếu cạnh (mặt cắt dẹt dày t) của DXF khách: chữ nhật mỏng có nét ngang nằm giữa chiều dày = bậc/hốc KHÔNG xuyên.
        Trả về [{'ax': 0|1, 'a','b' (khoảng dọc theo trục dài), 'lo','hi' (hai mặt, t = hi-lo), 'steps': [(xa, xb, depth|None, 'trên'|'dưới'|'')]}].
        ax=0: mỏng theo y (hình chiếu cạnh đặt dưới/trên hình phẳng); ax=1: mỏng theo x (đặt bên cạnh)."""
        if hasattr(self, '_prof'):
            return self._prof
        out = []
        for ax in (0, 1):
            L = [(l[0], l[1], l[2], l[3]) if ax == 0 else (l[1], l[0], l[3], l[2]) for l in self.lines]
            hor = defaultdict(list)       # y -> [(xa, xb)]
            ver = defaultdict(list)       # x -> [(ya, yb)]
            for x1, y1, x2, y2 in L:
                if abs(y1 - y2) <= 0.005 and abs(x1 - x2) >= 0.5:
                    hor[round(y1, 2)].append((min(x1, x2), max(x1, x2)))
                elif abs(x1 - x2) <= 0.005 and abs(y1 - y2) >= 0.1:
                    ver[round(x1, 2)].append((min(y1, y2), max(y1, y2)))

            def cover(lst, a, b):
                """phần trăm đoạn [a, b] được phủ bởi các đoạn trong lst"""
                tot = 0.0
                for u, v in sorted(lst):
                    u, v = max(u, a), min(v, b)
                    if v > u:
                        tot += v - u
                return tot / (b - a) if b > a else 0.0
            ys = sorted(hor)
            for i, lo in enumerate(ys):
                for hi in ys[i + 1:]:
                    t = hi - lo
                    if t > 30:
                        break
                    if t < 0.3:
                        continue
                    for (a, b) in [r for r in hor[lo] if r[1] - r[0] >= max(20.0, 4 * t)]:
                        if not any(abs(a - u) <= 0.05 and abs(b - v) <= 0.05 for u, v in hor[hi]):
                            continue
                        xa = [x for x in ver if abs(x - a) <= 0.05]
                        xb = [x for x in ver if abs(x - b) <= 0.05]
                        if not (xa and xb) or max(cover(ver[x], lo, hi) for x in xa) < 0.9 or max(cover(ver[x], lo, hi) for x in xb) < 0.9:
                            continue
                        steps = []
                        for y, segs in hor.items():
                            if y <= lo + 0.15 or y >= hi - 0.15:
                                continue
                            for u, v in sorted(segs):
                                u, v = max(u, a), min(v, b)
                                if v - u < 1.0:
                                    continue
                                if steps and steps[-1][2] == y and u <= steps[-1][1] + 0.05:
                                    steps[-1][1] = max(steps[-1][1], v)
                                else:
                                    steps.append([u, v, y])
                        res = []
                        for u, v, y in steps:
                            up = max([cover(ver[x], y, hi) for x in ver if abs(x - u) <= 0.05 or abs(x - v) <= 0.05] or [0])
                            dn = max([cover(ver[x], lo, y) for x in ver if abs(x - u) <= 0.05 or abs(x - v) <= 0.05] or [0])
                            if up >= 0.9:
                                res.append((u, v, round(hi - y, 3), 'trên'))
                            elif dn >= 0.9:
                                res.append((u, v, round(y - lo, 3), 'dưới'))
                            else:
                                res.append((u, v, None, ''))
                        if res:
                            out.append({'ax': ax, 'a': a, 'b': b, 'lo': lo, 'hi': hi, 'steps': res})
        self._prof = out
        return out

    def centers(self, p, tol=TOL):
        gx, gy = int(math.floor(p[0])), int(math.floor(p[1]))
        out = []
        for ix in (gx - 1, gx, gx + 1):
            for iy in (gy - 1, gy, gy + 1):
                for c in self.cgrid.get((ix, iy), ()):
                    if abs(c[0] - p[0]) <= tol and abs(c[1] - p[1]) <= tol:
                        out.append(c)
        return out


# ---------------------------------------------------------------- tìm phép đặt
def samples(e, n):
    if e[0] == 'L':
        return [(e[1][0] + (e[2][0] - e[1][0]) * k / (n - 1), e[1][1] + (e[2][1] - e[1][1]) * k / (n - 1)) for k in range(n)]
    if e[0] == 'A':
        return [arc_pt(e[1], e[2], e[3] + e[4] * k / (n - 1)) for k in range(n)]
    return [e[1]]


def length(e):
    if e[0] == 'L':
        return math.hypot(e[2][0] - e[1][0], e[2][1] - e[1][1])
    if e[0] == 'A':
        return math.radians(e[4]) * e[2]
    return 0.0


def is_corner(e):
    return e[0] == 'A' and e[2] <= 3.01 and e[4] < 180      # bo R laser ở góc (kể cả góc không vuông)


def score(ents, K, d, quick=False):
    """(tỉ lệ chiều dài biên nằm trên nét khách, số lỗ trùng tâm)"""
    tot = hit = 0.0
    holes = 0
    cut = [e for e in ents if e[0] != 'C' and not is_corner(e)]
    if quick:
        cut = sorted(cut, key=length, reverse=True)[:12]
    for e in cut:
        L = length(e)
        ps = samples(e, 3)
        ok = sum(1 for p in ps if K.dist((p[0] + d[0], p[1] + d[1]), 1.0) <= TOL)
        tot += L
        hit += L * ok / len(ps)
    for e in ents:
        if e[0] == 'C' and K.centers((e[1][0] + d[0], e[1][1] + d[1])):
            holes += 1
    return (hit / tot if tot else 0.0), holes


def top(votes, n):
    return [k for k, v in sorted(votes.items(), key=lambda z: -z[1])[:n]]


def best_fit(part, K):
    nh = sum(1 for e in part if e[0] == 'C')
    best = None
    for oi, (oname, fn) in enumerate(ORI):
        ents = [tf_ent(e, fn, oi >= 4) for e in part]
        cand = {}
        jv, js = defaultdict(int), {}
        for e in ents:                                   # phiếu theo tâm lỗ
            if e[0] != 'C':
                continue
            for lst in (K.circ, [a for a in K.arcs if a[2] <= 30 and a[4] >= 180]):
                for c in lst:
                    dx, dy = c[0] - e[1][0], c[1] - e[1][1]
                    k = (round(dx, 1), round(dy, 1))
                    jv[k] += 1
                    js[k] = (dx, dy)
        for k in top(jv, 8):
            if jv[k] >= min(2, nh):
                cand[k] = js[k]
        vx, vy, sx, sy = defaultdict(float), defaultdict(float), {}, {}
        for e in ents:                                   # phiếu theo cạnh ngang/dọc
            if e[0] != 'L':
                continue
            L = length(e)
            if L < 5:
                continue
            hz, vt = abs(e[1][1] - e[2][1]) < 1e-4, abs(e[1][0] - e[2][0]) < 1e-4
            if not (hz or vt):
                continue
            for x1, y1, x2, y2 in K.lines:
                if hz and abs(y1 - y2) < 1e-4 and abs(x1 - x2) >= 5:
                    k = round(y1 - e[1][1], 1)
                    vy[k] += min(L, abs(x1 - x2))
                    sy[k] = y1 - e[1][1]
                elif vt and abs(x1 - x2) < 1e-4 and abs(y1 - y2) >= 5:
                    k = round(x1 - e[1][0], 1)
                    vx[k] += min(L, abs(y1 - y2))
                    sx[k] = x1 - e[1][0]
        for kx in top(vx, 6):
            for ky in top(vy, 6):
                cand[(kx, ky)] = (sx[kx], sy[ky])
        quick = sorted(((score(ents, K, d, True), d) for d in cand.values()), key=lambda z: -(z[0][0] * 0.6 + (z[0][1] / nh if nh else 0) * 0.4))[:3]
        for _, d in quick:
            so, hh = score(ents, K, d)
            val = so * 0.6 + (hh / nh if nh else so) * 0.4
            if best is None or val > best[0] + 1e-9:
                best = (val, so, hh, oname, d, ents)
    return best


# ---------------------------------------------------------------- so chi tiết
def compare(code, part, flags, K, fit, flat, greens=()):
    val, so, hh, oname, d, ents = fit
    nh = sum(1 for e in part if e[0] == 'C')
    xs = [p[0] for e in part for p in (samples(e, 3) if e[0] != 'C' else [(e[1][0] - e[2], e[1][1] - e[2]), (e[1][0] + e[2], e[1][1] + e[2])])]
    ys = [p[1] for e in part for p in (samples(e, 3) if e[0] != 'C' else [(e[1][0] - e[2], e[1][1] - e[2]), (e[1][0] + e[2], e[1][1] + e[2])])]
    ox, oy = min(xs), min(ys)
    loc = lambda p: '(%s; %s)' % (f(p[0] - ox), f(p[1] - oy))           # toạ độ trong hình AI, gốc ở góc dưới trái khung bao
    noflag = flags is None
    has1 = any(FLAG1.lower() in x.lower() for x in flags or [])
    has18 = noflag or any(FLAG18.lower() in x.lower() for x in flags or [])
    res = {'ma': code, 'file_khach': os.path.basename(K.path), 'phep_dat': oname, 'khop_bien': round(so, 3), 'lo_trung_tam': '%d/%d' % (hh, nh),
           'kieu': 'hình phẳng' if flat else 'cụm lỗ', 'flag1': has1, 'khac_biet': []}

    def add(loai, muc, mo_ta, flag_khong_lien_quan=False):
        x = {'loai': loai, 'muc': muc, 'mo_ta': mo_ta}
        if flag_khong_lien_quan:
            x['khong_xet_flag'] = True                   # cảnh báo mà Flag 1 không phải cách xử lý (vd hốc không xuyên): không kéo theo "Thiếu Flag"
        res['khac_biet'].append(x)
    grp = defaultdict(list)
    used = set()
    for e0, e in zip(part, ents):
        if e[0] != 'C':
            continue
        p = (e[1][0] + d[0], e[1][1] + d[1])
        cs = K.centers(p)
        dia = round(2 * e[2], 2)
        if not cs:
            if flat:
                near = [c for c in K.circ if abs(c[2] - e[2]) <= 0.02 and math.hypot(c[0] - p[0], c[1] - p[1]) <= 5]
                if near:
                    c = min(near, key=lambda c: math.hypot(c[0] - p[0], c[1] - p[1]))
                    grp[('Sai vị trí lỗ', 'φ%s lệch so với DXF khách (dx %s, dy %s theo hướng DXF khách)' % (f(dia), f(p[0] - c[0]), f(p[1] - c[1])))].append(e0[1])
                else:
                    grp[('Thừa lỗ', 'φ%s không có vòng tròn nào cùng tâm trong DXF khách' % f(dia))].append(e0[1])
            continue
        for c in cs:
            used.add((round(c[0], 2), round(c[1], 2)))
        full = sorted({round(2 * c[2], 2) for c in cs if c[3] == 'C'})
        allr = sorted({round(2 * c[2], 2) for c in cs})
        if any(abs(dia - x) <= 0.02 for x in allr):
            inner = [x for x in full if x < dia - 0.3]
            if inner and abs(dia - max(allr)) <= 0.02:
                grp[('Sai kích thước lỗ', 'AI vẽ φ%s là vòng NGOÀI của nhóm vòng đồng tâm trong DXF khách (%s): nếu là khoét đầu vít chìm/ザグリ hoặc ký hiệu ren thì lỗ cắt là vòng trong φ%s' % (f(dia), ', '.join('φ' + f(x) for x in allr), f(max(inner))))].append(e0[1])
            continue
        nominal = max(allr)
        pil = PILOT_D.get(nominal if nominal != int(nominal) else int(nominal))
        if pil is not None and abs(dia - pil) <= 0.02:
            continue                                     # lỗ mồi đúng cỡ ren của ký hiệu ren
        mine = [m for m, v in PILOT_D.items() if abs(v - dia) <= 0.02]
        if pil is not None and len(allr) >= 2 and mine:
            grp[('Sai kích thước lỗ', 'AI vẽ φ%s (lỗ mồi M%s) nhưng ký hiệu ren DXF khách là M%s (vòng %s): lỗ mồi theo DXF là φ%s' % (f(dia), f(mine[0]), f(nominal), ', '.join('φ' + f(x) for x in allr), f(pil)))].append(e0[1])
        else:
            grp[('Sai kích thước lỗ', 'AI vẽ φ%s, DXF khách cùng tâm là %s' % (f(dia), ', '.join('φ' + f(x) for x in allr)))].append(e0[1])
    for (loai, txt), pts in grp.items():
        soft = has1 and 'vòng NGOÀI' not in txt
        add(loai, 'thongtin' if soft else 'canhbao', '%d lỗ tại %s: %s%s' % (len(pts), ', '.join(loc(p) for p in pts[:6]) + (' …' if len(pts) > 6 else ''), txt, ' (mã đã có Flag 1: đối chiếu nội dung Flag)' if soft else ''))
    if flat:
        bad = []
        for e0, e in zip(part, ents):
            if e[0] == 'C':
                continue
            ps = samples(e, 9)
            ds = [K.dist((p[0] + d[0], p[1] + d[1]), 8.0) for p in ps]
            if is_corner(e):
                if max(ds[0], ds[-1]) <= TOL or max(ds) <= TOL:
                    continue                             # bo R laser ở góc nhọn của khách
            if max(ds) > TOL:
                bad.append((e0, max(ds), sum(1 for x in ds if x > TOL) / len(ds)))
        if any(fr >= 0.5 for _, _, fr in bad):
            bad = [b for b in bad if b[2] >= 0.2]          # bỏ đoạn lệch ngắn là hệ quả của cạnh/cung bên cạnh
        for e0, dm, fr in sorted(bad, key=lambda z: -z[1])[:8]:
            if e0[0] == 'L':
                what = 'cạnh %s-%s' % (loc(e0[1]), loc(e0[2]))
            else:
                what = 'cung R%s tâm %s' % (f(e0[2]), loc(e0[1]))
            soft = has1 or (has18 and dm <= 0.6)
            why = ' (mã đã có Flag 1: đối chiếu nội dung Flag)' if has1 else (' (lệch ≤ 0.6: có thể do lấy giữa dung sai)' if noflag else ' (mã có Flag dung sai, lệch ≤ 0.6: có thể do lấy giữa dung sai)') if soft else ''
            add('Sai biên dạng ngoài', 'thongtin' if soft else 'canhbao', '%s không nằm trên nét của DXF khách, lệch %s%s (%d%% chiều dài)%s' % (what, '≥ ' if dm >= 8 else '', f(dm), round(fr * 100), why))
        if len(bad) > 8:
            add('Sai biên dạng ngoài', 'thongtin', 'còn %d cạnh/cung khác không nằm trên nét DXF khách' % (len(bad) - 8))
        # lỗ khách có mà hình AI không có (chỉ xét trong khung bao hình AI đã đặt lên DXF khách)
        ex = [(p[0] + d[0], p[1] + d[1]) for e in ents for p in (samples(e, 3) if e[0] != 'C' else [e[1]])]
        x0, x1, y0, y1 = min(p[0] for p in ex), max(p[0] for p in ex), min(p[1] for p in ex), max(p[1] for p in ex)
        inv = {v: k for k, v in enumerate(ORI)}
        miss = defaultdict(list)
        for cx, cy, r in K.circ:
            if x0 + r <= cx <= x1 - r and y0 + r <= cy <= y1 - r and (round(cx, 2), round(cy, 2)) not in used and r <= 100:
                if not any(abs(c[0] - cx) <= TOL and abs(c[1] - cy) <= TOL for c in [(e[1][0] + d[0], e[1][1] + d[1]) for e in ents if e[0] == 'C']):
                    miss[round(2 * r, 2)].append((cx, cy))
        for dia, pts in sorted(miss.items()):
            cen = {(round(p[0], 1), round(p[1], 1)) for p in pts}
            tron = abs(dia * 10 - round(dia * 10)) < 1e-6      # φ lẻ (4.13, 67.46...) thường là ký hiệu ren hoặc vòng chú thích
            add('Thiếu lỗ', 'thongtin' if has1 or not tron else 'canhbao', 'DXF khách có %d vòng φ%s trong vùng hình mà hình AI không có lỗ cùng tâm (lỗ bị gạch/hình chiếu khác đè lên thì bỏ qua)' % (len(cen), f(dia)))
        # hốc/rãnh/bậc không xuyên: hình chiếu cạnh của DXF khách có nét ngang giữa chiều dày mà hình AI vẽ cạnh/cung đúng đoạn đó
        for pr in K.profiles():
            ax = pr['ax']
            lo_ai, hi_ai = (x0, x1) if ax == 0 else (y0, y1)
            o0, o1 = (y0, y1) if ax == 0 else (x0, x1)
            if abs(pr['a'] - lo_ai) > 0.3 or abs(pr['b'] - hi_ai) > 0.3:
                continue
            if min(o1, pr['hi']) - max(o0, pr['lo']) > 0.5 * (pr['hi'] - pr['lo']):
                continue                                        # chữ nhật mỏng này chính là hình phẳng, không phải hình chiếu cạnh
            t = pr['hi'] - pr['lo']
            for u, v, dep, side in pr['steps']:
                if any(abs((u + v) / 2 - (c[ax])) <= 0.06 and abs((v - u) / 2 - c[2]) <= 0.06 for c in K.circ):
                    continue                                    # khoét đầu vít/ザグリ: đã kiểm ở vòng đồng tâm
                hit = []
                for e0, e in zip(part, ents):
                    if e[0] == 'C' or is_corner(e) or length(e) < 1.0:
                        continue
                    ps = [(p[0] + d[0], p[1] + d[1]) for p in samples(e, 9)]
                    if all(u - 0.1 <= p[ax] <= v + 0.1 for p in ps):
                        hit.append(e0)
                if hit:
                    where = ', '.join(('%s-%s' % (loc(h[1]), loc(h[2])) if h[0] == 'L' else 'cung R%s tâm %s' % (f(h[2]), loc(h[1]))) for h in hit[:3])
                    add('Sai biên dạng ngoài', 'canhbao', 'Hình chiếu cạnh DXF khách (dày %s) có hốc/bậc KHÔNG xuyên ở đoạn %s %s đến %s (rộng %s%s) nhưng hình AI vẽ %d cạnh/cung nằm trọn trong đoạn đó (%s): phần không xuyên hết chiều dày thì không vẽ làm biên cắt; kiểm PDF xem có phải nét gạch/hốc nửa chiều dày' % (f(t), 'x' if ax == 0 else 'y', f(u), f(v), f(v - u), ', sâu %s từ mặt %s' % (f(dep), side) if dep is not None else '', len(hit), where), True)
    if any(x['muc'] == 'canhbao' and not x.get('khong_xet_flag') for x in res['khac_biet']) and not has1 and not noflag:
        add('Thiếu Flag', 'canhbao', 'Hình khác DXF khách nhưng mã không có Flag 1 ("%s")' % FLAG1)
    return res


def src_dxf(src):
    out = []
    for fn in sorted(os.listdir(src)):
        u = fn.upper()
        if u.endswith('.DXF') and not u.endswith('_ALL.DXF') and not re.match(r'26-\d{6}[TF]?\.DXF', u) and os.path.isfile(os.path.join(src, fn)):
            out.append(os.path.join(src, fn))
    return out


def run(path, src, only=None):
    parts = [(c, [e for e in es if e[0] not in ('B', 'G')], fl, any(e[0] == 'B' for e in es), [e for e in es if e[0] == 'G']) for c, es, fl in load_ai(path)]
    ks, errs = [], []
    for p in src_dxf(src):
        try:
            ks.append(Khach(p))
        except Exception as ex:
            errs.append('Không đọc được DXF khách %s: %s' % (os.path.basename(p), ex))
    out = {'file': os.path.basename(path), 'dxf_khach': [os.path.basename(k.path) for k in ks], 'loi_doc': errs, 'ket_qua': []}
    for code, part, flags, bent, greens in parts:
        if only and code not in only:
            continue
        if not ks:
            out['ket_qua'].append({'ma': code, 'kieu': 'không có DXF khách', 'khac_biet': []})
            continue
        nh = sum(1 for e in part if e[0] == 'C')
        best = None
        for K in ks:
            fit = best_fit(part, K)
            if fit and (best is None or fit[0] > best[1][0]):
                best = (K, fit)
        if best is None:
            out['ket_qua'].append({'ma': code, 'kieu': 'không đối chiếu được', 'khac_biet': []})
            continue
        K, fit = best
        so, hh = fit[1], fit[2]
        flat = so >= (0.9 if bent else 0.6)             # chi tiết uốn: hình trải hiếm khi trùng hình chiếu, chỉ so cụm lỗ
        if flat or (hh >= 2 and hh >= 0.5 * nh):
            out['ket_qua'].append(compare(code, part, flags, K, fit, flat, greens))
        else:
            out['ket_qua'].append({'ma': code, 'kieu': 'không đối chiếu được', 'khop_bien': round(so, 3), 'lo_trung_tam': '%d/%d' % (hh, nh),
                                   'ghi_chu': 'Không hình chiếu nào của DXF khách chồng khít hình AI (chi tiết uốn, DXF khác tỉ lệ, hoặc không có DXF của mã này)', 'khac_biet': []})
    return out


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('file')
    ap.add_argument('--src')
    ap.add_argument('--code')
    ap.add_argument('--json', action='store_true')
    a = ap.parse_args()
    try:
        out = run(a.file, a.src or os.path.dirname(os.path.abspath(a.file)), set(a.code.split(',')) if a.code else None)
    except Exception as ex:
        print('LỖI: %s' % ex)
        sys.exit(2)
    warn = sum(1 for r in out['ket_qua'] for x in r['khac_biet'] if x['muc'] == 'canhbao')
    if a.json:
        print(json.dumps(out, ensure_ascii=False, indent=1))
    else:
        print('=== doi_chieu_khach: %s, %d DXF khách ===' % (out['file'], len(out['dxf_khach'])))
        for m in out['loi_doc']:
            print(' ! ' + m)
        for r in out['ket_qua']:
            head = '%s: %s' % (r['ma'], r['kieu'])
            if r.get('file_khach'):
                head += ' | %s | %s | biên khớp %d%%, lỗ trùng tâm %s' % (r['file_khach'], r['phep_dat'], round(r['khop_bien'] * 100), r['lo_trung_tam'])
            print(head)
            if r.get('ghi_chu'):
                print('   - ' + r['ghi_chu'])
            for x in r['khac_biet']:
                print('   [%s] %s: %s' % ('CẢNH BÁO' if x['muc'] == 'canhbao' else 'THÔNG TIN', x['loai'], x['mo_ta']))
    sys.exit(1 if warn else 0)


if __name__ == '__main__':
    main()

# -*- coding: utf-8 -*-
"""doi_chieu_khach.py - đối chiếu hình AI đã vẽ (file <đơn>_ALL.dxf hoặc file riêng) với DXF khách trong thư mục đơn.
Không cần AI: chạy local, 0 token. Chỉ BÁO chỗ khác, không sửa file.

Dùng:  py -X utf8 doi_chieu_khach.py <ALL.dxf | 26-xxxxxx.dxf> [--src THU_MUC_DON] [--code 068884,068885] [--json]
Mã thoát: 0 = không có cảnh báo, 1 = có cảnh báo, 2 = lỗi đọc file.

Cách làm: mở DXF khách (cả BLOCK/INSERT, POLYLINE), tìm phép đặt (8 hướng + tịnh tiến, tỉ lệ 1:1) cho hình AI chồng
khít nhất lên một hình chiếu của khách, rồi so:
  - lỗ: cùng tâm mà khác φ; AI lấy vòng ngoài của nhóm vòng đồng tâm (khoét đầu vít chìm/ザグリ, ký hiệu ren);
    lỗ mồi không đúng cỡ ren của ký hiệu ren DXF khách; lỗ lệch vị trí; lỗ khách có mà hình AI không có;
  - biên dạng: cạnh/cung của hình AI không nằm trên nét nào của DXF khách (kèm độ lệch);
  - hốc/rãnh/bậc không xuyên: hình chiếu cạnh của DXF khách (chữ nhật mỏng bằng chiều dày, cùng bề rộng hình phẳng) có nét ngang nằm giữa
    chiều dày mà hình AI vẽ cạnh/cung đúng đoạn đó -> CẢNH BÁO (phần không xuyên hết chiều dày không vẽ làm biên cắt); bỏ qua khoét đầu vít/ザグリ.
Chỗ khác mà mã đó không có Flag 1 ("Kích thước PDF và DXF khác nhau") thì báo CẢNH BÁO (thiếu Flag 1 hoặc vẽ sai).
Giới hạn: chi tiết uốn chỉ đối chiếu được cụm lỗ (hình trải không trùng hình chiếu); DXF khách vẽ khác tỉ lệ 1:1 thì bỏ qua;
không biết nét bị gạch tay trên PDF, không biết mặt ngoài/kegaki. Kết quả là gợi ý để xem lại, không phải kết luận.
"""
import argparse
import json
import math
import os
import re
import sys
import unicodedata
from collections import defaultdict

import ezdxf

TOL = 0.05            # sai số coi là trùng
CELL = 10.0
ORI = [
    ('giữ nguyên hướng', lambda x, y: (x, y)),
    ('xoay 180°', lambda x, y: (-x, -y)),
    ('xoay 90° ngược chiều kim đồng hồ', lambda x, y: (-y, x)),
    ('xoay 90° cùng chiều kim đồng hồ', lambda x, y: (y, -x)),
    ('lật trái-phải', lambda x, y: (-x, y)),
    ('lật trên-dưới', lambda x, y: (x, -y)),
    ('xoay 90° rồi lật', lambda x, y: (y, x)),
    ('xoay 270° rồi lật', lambda x, y: (-y, -x)),
]
# lỗ mồi taro theo cỡ ren (Quy_Tac_Lo_Moi.md); chỉ dùng để nhận ra ký hiệu ren, không thay bảng gốc
PILOT_D = {2: 1.6, 2.5: 2.1, 2.6: 2.2, 3: 2.5, 3.5: 2.9, 4: 3.3, 5: 4.2, 6: 5.0, 7: 6.0, 8: 6.8, 10: 8.5, 12: 10.3, 14: 12.0, 16: 14.0}
FLAG1 = 'Kích thước PDF và DXF khác nhau'
FLAG18 = 'Kích thước có dung sai'


def f(v):
    return ('%.3f' % v).rstrip('0').rstrip('.')


def decode_u(s):
    return unicodedata.normalize('NFC', re.sub(r'\\U\+([0-9A-Fa-f]{4})', lambda m: chr(int(m.group(1), 16)), s))


# ---------------------------------------------------------------- hình AI
def col_of(e):
    c = e.dxf.color if e.dxf.hasattr('color') else 256
    return 7 if c in (0, 7, 256) else c


def arc_pt(c, r, a):
    return (c[0] + r * math.cos(math.radians(a)), c[1] + r * math.sin(math.radians(a)))


def load_ai(path):
    """Trả về [(mã, [entity], [câu Flag])]. entity: ('L', p1, p2) | ('A', tâm, R, a0, quét) | ('C', tâm, R); chỉ nét cắt trắng."""
    doc = ezdxf.readfile(path)
    ents, codes, flags = [], [], []
    for e in doc.modelspace():
        t = e.dxftype()
        if t == 'TEXT':
            tx = e.dxf.text.strip()
            if re.fullmatch(r'\d{6}', tx):
                codes.append((e.dxf.insert.y, tx))
            elif col_of(e) == 6:
                flags.append((e.dxf.insert.y, decode_u(tx)))
            continue
        lt = (e.dxf.linetype if e.dxf.hasattr('linetype') else '').upper()
        if col_of(e) == 3 and lt != 'DASHED' and t in ('LINE', 'ARC'):
            if t == 'LINE':
                ents.append(('G', (e.dxf.start.x, e.dxf.start.y), (e.dxf.end.x, e.dxf.end.y)))   # rạch Green: chỉ để biết quanh góc có rạch hay không
            else:
                ents.append(('G', arc_pt((e.dxf.center.x, e.dxf.center.y), e.dxf.radius, e.dxf.start_angle), arc_pt((e.dxf.center.x, e.dxf.center.y), e.dxf.radius, e.dxf.end_angle)))
            continue
        if col_of(e) != 7 or lt == 'DASHED':
            if lt == 'DASHED' and t == 'LINE':
                ents.append(('B', (e.dxf.start.x, e.dxf.start.y), (e.dxf.end.x, e.dxf.end.y)))   # đường uốn: chỉ để biết chi tiết có uốn
            continue                      # đường uốn, kegaki, rạch Green: không có trong DXF khách theo cùng nghĩa
        if t == 'LINE':
            ents.append(('L', (e.dxf.start.x, e.dxf.start.y), (e.dxf.end.x, e.dxf.end.y)))
        elif t == 'CIRCLE':
            ents.append(('C', (e.dxf.center.x, e.dxf.center.y), e.dxf.radius))
        elif t == 'ARC':
            ents.append(('A', (e.dxf.center.x, e.dxf.center.y), e.dxf.radius, e.dxf.start_angle, (e.dxf.end_angle - e.dxf.start_angle) % 360))
    if not codes:
        m = re.search(r'(\d{6})', os.path.basename(path))
        return [(m.group(1) if m else os.path.basename(path), ents, None)]      # file riêng: không có Flag để xét

    def yr(e):
        if e[0] in ('L', 'B', 'G'):
            return min(e[1][1], e[2][1]), max(e[1][1], e[2][1])
        if e[0] == 'A':
            ys = [arc_pt(e[1], e[2], e[3] + e[4] * k / 8)[1] for k in range(9)]
            return min(ys), max(ys)
        return e[1][1] - e[2], e[1][1] + e[2]
    bands = []
    for y0, y1, e in sorted(((yr(e)[0], yr(e)[1], e) for e in ents), key=lambda z: z[0]):
        if bands and y0 <= bands[-1][1] + 100:
            bands[-1][1] = max(bands[-1][1], y1)
            bands[-1][2].append(e)
        else:
            bands.append([y0, y1, [e]])
    codes.sort(reverse=True)
    out = []
    for y0, y1, es in reversed(bands):
        cd = [c for y, c in codes if y0 - 1 <= y <= y1 + 1]
        if not cd:
            continue
        cy = next(y for y, c in codes if c == cd[0])
        nxt = max([y for y, c in codes if y < cy] or [-1e18])
        fl = ' '.join(t for y, t in sorted(flags, reverse=True) if nxt < y < cy)
        out.append((cd[0], es, [x.strip() for x in re.split(r'(?:^|\s)\d+\.\s', fl) if x.strip()]))
    return out


def tf_ent(e, fn, mirror):
    if e[0] == 'L':
        return ('L', fn(*e[1]), fn(*e[2]))
    if e[0] == 'C':
        return ('C', fn(*e[1]), e[2])
    c = fn(*e[1])
    p0, p1 = fn(*arc_pt(e[1], e[2], e[3])), fn(*arc_pt(e[1], e[2], e[3] + e[4]))
    if mirror:
        p0, p1 = p1, p0
    a0 = math.degrees(math.atan2(p0[1] - c[1], p0[0] - c[0]))
    return ('A', c, e[2], a0, e[4])


# ---------------------------------------------------------------- DXF khách
class Khach:
    def __init__(self, path):
        self.path = path
        self.lines, self.circ, self.arcs = [], [], []
        self.red = []                         # nét đỏ (màu 1) ngắn: chỗ khách chỉ rạch ở góc lõm
        self._walk(ezdxf.readfile(path).modelspace(), 0)
        self.grid = defaultdict(list)
        for i, (x1, y1, x2, y2) in enumerate(self.lines):
            n = max(1, int(math.hypot(x2 - x1, y2 - y1) / (CELL / 2)))
            seen = set()
            for k in range(n + 1):
                key = (int(math.floor((x1 + (x2 - x1) * k / n) / CELL)), int(math.floor((y1 + (y2 - y1) * k / n) / CELL)))
                if key not in seen:
                    seen.add(key)
                    self.grid[key].append(('L', i))
        for kind, lst in (('C', self.circ), ('A', self.arcs)):
            for i, it in enumerate(lst):
                cx, cy, r = it[0], it[1], it[2]
                n = max(8, int(2 * math.pi * r / (CELL / 2)))
                seen = set()
                for k in range(n):
                    a = 2 * math.pi * k / n
                    key = (int(math.floor((cx + r * math.cos(a)) / CELL)), int(math.floor((cy + r * math.sin(a)) / CELL)))
                    if key not in seen:
                        seen.add(key)
                        self.grid[key].append((kind, i))
        self.cgrid = defaultdict(list)       # tâm vòng tròn và cung nhỏ (ký hiệu ren)
        for cx, cy, r in self.circ:
            self.cgrid[(int(math.floor(cx)), int(math.floor(cy)))].append((cx, cy, r, 'C'))
        for cx, cy, r, a0, sw in self.arcs:
            if r <= 30 and sw >= 180:
                self.cgrid[(int(math.floor(cx)), int(math.floor(cy)))].append((cx, cy, r, 'A'))

    def _walk(self, ents, depth):
        for e in ents:
            t = e.dxftype()
            try:
                if t == 'INSERT' and depth < 5:
                    self._walk(e.virtual_entities(), depth + 1)
                elif t in ('LWPOLYLINE', 'POLYLINE'):
                    self._walk(e.virtual_entities(), depth + 1)
                elif t == 'LINE':
                    self.lines.append((e.dxf.start.x, e.dxf.start.y, e.dxf.end.x, e.dxf.end.y))
                    if e.dxf.color == 1 and 0.3 <= math.hypot(e.dxf.end.x - e.dxf.start.x, e.dxf.end.y - e.dxf.start.y) <= 3.0:
                        self.red.append((e.dxf.start.x, e.dxf.start.y, e.dxf.end.x, e.dxf.end.y))
                elif t == 'CIRCLE':
                    flip = e.dxf.extrusion.z < 0          # BLOCK chèn lật (extrusion -Z): toạ độ đang ở OCS, đổi về WCS
                    self.circ.append((-e.dxf.center.x if flip else e.dxf.center.x, e.dxf.center.y, e.dxf.radius))
                elif t == 'ARC':
                    sw = (e.dxf.end_angle - e.dxf.start_angle) % 360
                    if e.dxf.extrusion.z < 0:
                        self.arcs.append((-e.dxf.center.x, e.dxf.center.y, e.dxf.radius, (180 - e.dxf.end_angle) % 360, sw))
                    else:
                        self.arcs.append((e.dxf.center.x, e.dxf.center.y, e.dxf.radius, e.dxf.start_angle, sw))
            except Exception:
                continue

    def dist(self, p, lim=CELL):
        """khoảng cách từ điểm tới nét gần nhất (chỉ tìm trong lim)"""
        gx, gy = int(math.floor(p[0] / CELL)), int(math.floor(p[1] / CELL))
        best = lim
        seen = set()
        for ix in (gx - 1, gx, gx + 1):
            for iy in (gy - 1, gy, gy + 1):
                for it in self.grid.get((ix, iy), ()):
                    if it in seen:
                        continue
                    seen.add(it)
                    if it[0] == 'L':
                        x1, y1, x2, y2 = self.lines[it[1]]
                        dx, dy = x2 - x1, y2 - y1
                        L2 = dx * dx + dy * dy
                        t = 0 if L2 == 0 else max(0, min(1, ((p[0] - x1) * dx + (p[1] - y1) * dy) / L2))
                        d = math.hypot(p[0] - x1 - t * dx, p[1] - y1 - t * dy)
                    elif it[0] == 'C':
                        cx, cy, r = self.circ[it[1]]
                        d = abs(math.hypot(p[0] - cx, p[1] - cy) - r)
                    else:
                        cx, cy, r, a0, sw = self.arcs[it[1]]
                        ang = (math.degrees(math.atan2(p[1] - cy, p[0] - cx)) - a0) % 360
                        if ang <= sw + 0.5 or ang >= 359.5:
                            d = abs(math.hypot(p[0] - cx, p[1] - cy) - r)
                        else:
                            d = min(math.hypot(p[0] - q[0], p[1] - q[1]) for q in (arc_pt((cx, cy), r, a0), arc_pt((cx, cy), r, a0 + sw)))
                    if d < best:
                        best = d
        return best

    def profiles(self):
        """Hình chiếu cạnh (mặt cắt dẹt dày t) của DXF khách: chữ nhật mỏng có nét ngang nằm giữa chiều dày = bậc/hốc KHÔNG xuyên.
        Trả về [{'ax': 0|1, 'a','b' (khoảng dọc theo trục dài), 'lo','hi' (hai mặt, t = hi-lo), 'steps': [(xa, xb, depth|None, 'trên'|'dưới'|'')]}].
        ax=0: mỏng theo y (hình chiếu cạnh đặt dưới/trên hình phẳng); ax=1: mỏng theo x (đặt bên cạnh)."""
        if hasattr(self, '_prof'):
            return self._prof
        out = []
        for ax in (0, 1):
            L = [(l[0], l[1], l[2], l[3]) if ax == 0 else (l[1], l[0], l[3], l[2]) for l in self.lines]
            hor = defaultdict(list)       # y -> [(xa, xb)]
            ver = defaultdict(list)       # x -> [(ya, yb)]
            for x1, y1, x2, y2 in L:
                if abs(y1 - y2) <= 0.005 and abs(x1 - x2) >= 0.5:
                    hor[round(y1, 2)].append((min(x1, x2), max(x1, x2)))
                elif abs(x1 - x2) <= 0.005 and abs(y1 - y2) >= 0.1:
                    ver[round(x1, 2)].append((min(y1, y2), max(y1, y2)))

            def cover(lst, a, b):
                """phần trăm đoạn [a, b] được phủ bởi các đoạn trong lst"""
                tot = 0.0
                for u, v in sorted(lst):
                    u, v = max(u, a), min(v, b)
                    if v > u:
                        tot += v - u
                return tot / (b - a) if b > a else 0.0
            ys = sorted(hor)
            for i, lo in enumerate(ys):
                for hi in ys[i + 1:]:
                    t = hi - lo
                    if t > 30:
                        break
                    if t < 0.3:
                        continue
                    for (a, b) in [r for r in hor[lo] if r[1] - r[0] >= max(20.0, 4 * t)]:
                        if not any(abs(a - u) <= 0.05 and abs(b - v) <= 0.05 for u, v in hor[hi]):
                            continue
                        xa = [x for x in ver if abs(x - a) <= 0.05]
                        xb = [x for x in ver if abs(x - b) <= 0.05]
                        if not (xa and xb) or max(cover(ver[x], lo, hi) for x in xa) < 0.9 or max(cover(ver[x], lo, hi) for x in xb) < 0.9:
                            continue
                        steps = []
                        for y, segs in hor.items():
                            if y <= lo + 0.15 or y >= hi - 0.15:
                                continue
                            for u, v in sorted(segs):
                                u, v = max(u, a), min(v, b)
                                if v - u < 1.0:
                                    continue
                                if steps and steps[-1][2] == y and u <= steps[-1][1] + 0.05:
                                    steps[-1][1] = max(steps[-1][1], v)
                                else:
                                    steps.append([u, v, y])
                        res = []
                        for u, v, y in steps:
                            up = max([cover(ver[x], y, hi) for x in ver if abs(x - u) <= 0.05 or abs(x - v) <= 0.05] or [0])
                            dn = max([cover(ver[x], lo, y) for x in ver if abs(x - u) <= 0.05 or abs(x - v) <= 0.05] or [0])
                            if up >= 0.9:
                                res.append((u, v, round(hi - y, 3), 'trên'))
                            elif dn >= 0.9:
                                res.append((u, v, round(y - lo, 3), 'dưới'))
                            else:
                                res.append((u, v, None, ''))
                        if res:
                            out.append({'ax': ax, 'a': a, 'b': b, 'lo': lo, 'hi': hi, 'steps': res})
        self._prof = out
        return out

    def centers(self, p, tol=TOL):
        gx, gy = int(math.floor(p[0])), int(math.floor(p[1]))
        out = []
        for ix in (gx - 1, gx, gx + 1):
            for iy in (gy - 1, gy, gy + 1):
                for c in self.cgrid.get((ix, iy), ()):
                    if abs(c[0] - p[0]) <= tol and abs(c[1] - p[1]) <= tol:
                        out.append(c)
        return out


# ---------------------------------------------------------------- tìm phép đặt
def samples(e, n):
    if e[0] == 'L':
        return [(e[1][0] + (e[2][0] - e[1][0]) * k / (n - 1), e[1][1] + (e[2][1] - e[1][1]) * k / (n - 1)) for k in range(n)]
    if e[0] == 'A':
        return [arc_pt(e[1], e[2], e[3] + e[4] * k / (n - 1)) for k in range(n)]
    return [e[1]]


def length(e):
    if e[0] == 'L':
        return math.hypot(e[2][0] - e[1][0], e[2][1] - e[1][1])
    if e[0] == 'A':
        return math.radians(e[4]) * e[2]
    return 0.0


def is_corner(e):
    return e[0] == 'A' and e[2] <= 3.01 and e[4] < 180      # bo R laser ở góc (kể cả góc không vuông)


def score(ents, K, d, quick=False):
    """(tỉ lệ chiều dài biên nằm trên nét khách, số lỗ trùng tâm)"""
    tot = hit = 0.0
    holes = 0
    cut = [e for e in ents if e[0] != 'C' and not is_corner(e)]
    if quick:
        cut = sorted(cut, key=length, reverse=True)[:12]
    for e in cut:
        L = length(e)
        ps = samples(e, 3)
        ok = sum(1 for p in ps if K.dist((p[0] + d[0], p[1] + d[1]), 1.0) <= TOL)
        tot += L
        hit += L * ok / len(ps)
    for e in ents:
        if e[0] == 'C' and K.centers((e[1][0] + d[0], e[1][1] + d[1])):
            holes += 1
    return (hit / tot if tot else 0.0), holes


def top(votes, n):
    return [k for k, v in sorted(votes.items(), key=lambda z: -z[1])[:n]]


def best_fit(part, K):
    nh = sum(1 for e in part if e[0] == 'C')
    best = None
    for oi, (oname, fn) in enumerate(ORI):
        ents = [tf_ent(e, fn, oi >= 4) for e in part]
        cand = {}
        jv, js = defaultdict(int), {}
        for e in ents:                                   # phiếu theo tâm lỗ
            if e[0] != 'C':
                continue
            for lst in (K.circ, [a for a in K.arcs if a[2] <= 30 and a[4] >= 180]):
                for c in lst:
                    dx, dy = c[0] - e[1][0], c[1] - e[1][1]
                    k = (round(dx, 1), round(dy, 1))
                    jv[k] += 1
                    js[k] = (dx, dy)
        for k in top(jv, 8):
            if jv[k] >= min(2, nh):
                cand[k] = js[k]
        vx, vy, sx, sy = defaultdict(float), defaultdict(float), {}, {}
        for e in ents:                                   # phiếu theo cạnh ngang/dọc
            if e[0] != 'L':
                continue
            L = length(e)
            if L < 5:
                continue
            hz, vt = abs(e[1][1] - e[2][1]) < 1e-4, abs(e[1][0] - e[2][0]) < 1e-4
            if not (hz or vt):
                continue
            for x1, y1, x2, y2 in K.lines:
                if hz and abs(y1 - y2) < 1e-4 and abs(x1 - x2) >= 5:
                    k = round(y1 - e[1][1], 1)
                    vy[k] += min(L, abs(x1 - x2))
                    sy[k] = y1 - e[1][1]
                elif vt and abs(x1 - x2) < 1e-4 and abs(y1 - y2) >= 5:
                    k = round(x1 - e[1][0], 1)
                    vx[k] += min(L, abs(y1 - y2))
                    sx[k] = x1 - e[1][0]
        for kx in top(vx, 6):
            for ky in top(vy, 6):
                cand[(kx, ky)] = (sx[kx], sy[ky])
        quick = sorted(((score(ents, K, d, True), d) for d in cand.values()), key=lambda z: -(z[0][0] * 0.6 + (z[0][1] / nh if nh else 0) * 0.4))[:3]
        for _, d in quick:
            so, hh = score(ents, K, d)
            val = so * 0.6 + (hh / nh if nh else so) * 0.4
            if best is None or val > best[0] + 1e-9:
                best = (val, so, hh, oname, d, ents)
    return best


# ---------------------------------------------------------------- so chi tiết
def compare(code, part, flags, K, fit, flat, greens=()):
    val, so, hh, oname, d, ents = fit
    nh = sum(1 for e in part if e[0] == 'C')
    xs = [p[0] for e in part for p in (samples(e, 3) if e[0] != 'C' else [(e[1][0] - e[2], e[1][1] - e[2]), (e[1][0] + e[2], e[1][1] + e[2])])]
    ys = [p[1] for e in part for p in (samples(e, 3) if e[0] != 'C' else [(e[1][0] - e[2], e[1][1] - e[2]), (e[1][0] + e[2], e[1][1] + e[2])])]
    ox, oy = min(xs), min(ys)
    loc = lambda p: '(%s; %s)' % (f(p[0] - ox), f(p[1] - oy))           # toạ độ trong hình AI, gốc ở góc dưới trái khung bao
    noflag = flags is None
    has1 = any(FLAG1.lower() in x.lower() for x in flags or [])
    has18 = noflag or any(FLAG18.lower() in x.lower() for x in flags or [])
    res = {'ma': code, 'file_khach': os.path.basename(K.path), 'phep_dat': oname, 'khop_bien': round(so, 3), 'lo_trung_tam': '%d/%d' % (hh, nh),
           'kieu': 'hình phẳng' if flat else 'cụm lỗ', 'flag1': has1, 'khac_biet': []}

    def add(loai, muc, mo_ta, flag_khong_lien_quan=False):
        x = {'loai': loai, 'muc': muc, 'mo_ta': mo_ta}
        if flag_khong_lien_quan:
            x['khong_xet_flag'] = True                   # cảnh báo mà Flag 1 không phải cách xử lý (vd hốc không xuyên): không kéo theo "Thiếu Flag"
        res['khac_biet'].append(x)
    grp = defaultdict(list)
    used = set()
    for e0, e in zip(part, ents):
        if e[0] != 'C':
            continue
        p = (e[1][0] + d[0], e[1][1] + d[1])
        cs = K.centers(p)
        dia = round(2 * e[2], 2)
        if not cs:
            if flat:
                near = [c for c in K.circ if abs(c[2] - e[2]) <= 0.02 and math.hypot(c[0] - p[0], c[1] - p[1]) <= 5]
                if near:
                    c = min(near, key=lambda c: math.hypot(c[0] - p[0], c[1] - p[1]))
                    grp[('Sai vị trí lỗ', 'φ%s lệch so với DXF khách (dx %s, dy %s theo hướng DXF khách)' % (f(dia), f(p[0] - c[0]), f(p[1] - c[1])))].append(e0[1])
                else:
                    grp[('Thừa lỗ', 'φ%s không có vòng tròn nào cùng tâm trong DXF khách' % f(dia))].append(e0[1])
            continue
        for c in cs:
            used.add((round(c[0], 2), round(c[1], 2)))
        full = sorted({round(2 * c[2], 2) for c in cs if c[3] == 'C'})
        allr = sorted({round(2 * c[2], 2) for c in cs})
        if any(abs(dia - x) <= 0.02 for x in allr):
            inner = [x for x in full if x < dia - 0.3]
            if inner and abs(dia - max(allr)) <= 0.02:
                grp[('Sai kích thước lỗ', 'AI vẽ φ%s là vòng NGOÀI của nhóm vòng đồng tâm trong DXF khách (%s): nếu là khoét đầu vít chìm/ザグリ hoặc ký hiệu ren thì lỗ cắt là vòng trong φ%s' % (f(dia), ', '.join('φ' + f(x) for x in allr), f(max(inner))))].append(e0[1])
            continue
        nominal = max(allr)
        pil = PILOT_D.get(nominal if nominal != int(nominal) else int(nominal))
        if pil is not None and abs(dia - pil) <= 0.02:
            continue                                     # lỗ mồi đúng cỡ ren của ký hiệu ren
        mine = [m for m, v in PILOT_D.items() if abs(v - dia) <= 0.02]
        if pil is not None and len(allr) >= 2 and mine:
            grp[('Sai kích thước lỗ', 'AI vẽ φ%s (lỗ mồi M%s) nhưng ký hiệu ren DXF khách là M%s (vòng %s): lỗ mồi theo DXF là φ%s' % (f(dia), f(mine[0]), f(nominal), ', '.join('φ' + f(x) for x in allr), f(pil)))].append(e0[1])
        else:
            grp[('Sai kích thước lỗ', 'AI vẽ φ%s, DXF khách cùng tâm là %s' % (f(dia), ', '.join('φ' + f(x) for x in allr)))].append(e0[1])
    for (loai, txt), pts in grp.items():
        soft = has1 and 'vòng NGOÀI' not in txt
        add(loai, 'thongtin' if soft else 'canhbao', '%d lỗ tại %s: %s%s' % (len(pts), ', '.join(loc(p) for p in pts[:6]) + (' …' if len(pts) > 6 else ''), txt, ' (mã đã có Flag 1: đối chiếu nội dung Flag)' if soft else ''))
    if flat:
        bad = []
        for e0, e in zip(part, ents):
            if e[0] == 'C':
                continue
            ps = samples(e, 9)
            ds = [K.dist((p[0] + d[0], p[1] + d[1]), 8.0) for p in ps]
            if is_corner(e):
                if max(ds[0], ds[-1]) <= TOL or max(ds) <= TOL:
                    continue                             # bo R laser ở góc nhọn của khách
            if max(ds) > TOL:
                bad.append((e0, max(ds), sum(1 for x in ds if x > TOL) / len(ds)))
        if any(fr >= 0.5 for _, _, fr in bad):
            bad = [b for b in bad if b[2] >= 0.2]          # bỏ đoạn lệch ngắn là hệ quả của cạnh/cung bên cạnh
        for e0, dm, fr in sorted(bad, key=lambda z: -z[1])[:8]:
            if e0[0] == 'L':
                what = 'cạnh %s-%s' % (loc(e0[1]), loc(e0[2]))
            else:
                what = 'cung R%s tâm %s' % (f(e0[2]), loc(e0[1]))
            soft = has1 or (has18 and dm <= 0.6)
            why = ' (mã đã có Flag 1: đối chiếu nội dung Flag)' if has1 else (' (lệch ≤ 0.6: có thể do lấy giữa dung sai)' if noflag else ' (mã có Flag dung sai, lệch ≤ 0.6: có thể do lấy giữa dung sai)') if soft else ''
            add('Sai biên dạng ngoài', 'thongtin' if soft else 'canhbao', '%s không nằm trên nét của DXF khách, lệch %s%s (%d%% chiều dài)%s' % (what, '≥ ' if dm >= 8 else '', f(dm), round(fr * 100), why))
        if len(bad) > 8:
            add('Sai biên dạng ngoài', 'thongtin', 'còn %d cạnh/cung khác không nằm trên nét DXF khách' % (len(bad) - 8))
        # lỗ khách có mà hình AI không có (chỉ xét trong khung bao hình AI đã đặt lên DXF khách)
        ex = [(p[0] + d[0], p[1] + d[1]) for e in ents for p in (samples(e, 3) if e[0] != 'C' else [e[1]])]
        x0, x1, y0, y1 = min(p[0] for p in ex), max(p[0] for p in ex), min(p[1] for p in ex), max(p[1] for p in ex)
        inv = {v: k for k, v in enumerate(ORI)}
        miss = defaultdict(list)
        for cx, cy, r in K.circ:
            if x0 + r <= cx <= x1 - r and y0 + r <= cy <= y1 - r and (round(cx, 2), round(cy, 2)) not in used and r <= 100:
                if not any(abs(c[0] - cx) <= TOL and abs(c[1] - cy) <= TOL for c in [(e[1][0] + d[0], e[1][1] + d[1]) for e in ents if e[0] == 'C']):
                    miss[round(2 * r, 2)].append((cx, cy))
        for dia, pts in sorted(miss.items()):
            cen = {(round(p[0], 1), round(p[1], 1)) for p in pts}
            tron = abs(dia * 10 - round(dia * 10)) < 1e-6      # φ lẻ (4.13, 67.46...) thường là ký hiệu ren hoặc vòng chú thích
            add('Thiếu lỗ', 'thongtin' if has1 or not tron else 'canhbao', 'DXF khách có %d vòng φ%s trong vùng hình mà hình AI không có lỗ cùng tâm (lỗ bị gạch/hình chiếu khác đè lên thì bỏ qua)' % (len(cen), f(dia)))
        # hốc/rãnh/bậc không xuyên: hình chiếu cạnh của DXF khách có nét ngang giữa chiều dày mà hình AI vẽ cạnh/cung đúng đoạn đó
        for pr in K.profiles():
            ax = pr['ax']
            lo_ai, hi_ai = (x0, x1) if ax == 0 else (y0, y1)
            o0, o1 = (y0, y1) if ax == 0 else (x0, x1)
            if abs(pr['a'] - lo_ai) > 0.3 or abs(pr['b'] - hi_ai) > 0.3:
                continue
            if min(o1, pr['hi']) - max(o0, pr['lo']) > 0.5 * (pr['hi'] - pr['lo']):
                continue                                        # chữ nhật mỏng này chính là hình phẳng, không phải hình chiếu cạnh
            t = pr['hi'] - pr['lo']
            for u, v, dep, side in pr['steps']:
                if any(abs((u + v) / 2 - (c[ax])) <= 0.06 and abs((v - u) / 2 - c[2]) <= 0.06 for c in K.circ):
                    continue                                    # khoét đầu vít/ザグリ: đã kiểm ở vòng đồng tâm
                hit = []
                for e0, e in zip(part, ents):
                    if e[0] == 'C' or is_corner(e) or length(e) < 1.0:
                        continue
                    ps = [(p[0] + d[0], p[1] + d[1]) for p in samples(e, 9)]
                    if all(u - 0.1 <= p[ax] <= v + 0.1 for p in ps):
                        hit.append(e0)
                if hit:
                    where = ', '.join(('%s-%s' % (loc(h[1]), loc(h[2])) if h[0] == 'L' else 'cung R%s tâm %s' % (f(h[2]), loc(h[1]))) for h in hit[:3])
                    add('Sai biên dạng ngoài', 'canhbao', 'Hình chiếu cạnh DXF khách (dày %s) có hốc/bậc KHÔNG xuyên ở đoạn %s %s đến %s (rộng %s%s) nhưng hình AI vẽ %d cạnh/cung nằm trọn trong đoạn đó (%s): phần không xuyên hết chiều dày thì không vẽ làm biên cắt; kiểm PDF xem có phải nét gạch/hốc nửa chiều dày' % (f(t), 'x' if ax == 0 else 'y', f(u), f(v), f(v - u), ', sâu %s từ mặt %s' % (f(dep), side) if dep is not None else '', len(hit), where), True)
        # nét đỏ ngắn của khách (rạch ở góc lõm): hình AI chép đúng nét đó thành LINE biên có một đầu cụt, quanh góc không có rạch Green
        if K.red:
            fn = dict(ORI)[oname]
            gp = [(fn(*q)[0] + d[0], fn(*q)[1] + d[1]) for g in greens for q in (g[1], g[2])]
            ends = [(q[0] + d[0], q[1] + d[1]) for e in ents if e[0] != 'C' for q in ((e[1], e[2]) if e[0] == 'L' else (arc_pt(e[1], e[2], e[3]), arc_pt(e[1], e[2], e[3] + e[4])))]
            same = lambda p, q: abs(p[0] - q[0]) <= TOL and abs(p[1] - q[1]) <= TOL
            rach = []
            for e0, e in zip(part, ents):
                if e[0] != 'L':
                    continue
                a, b = (e[1][0] + d[0], e[1][1] + d[1]), (e[2][0] + d[0], e[2][1] + d[1])
                if not any((same(a, (r[0], r[1])) and same(b, (r[2], r[3]))) or (same(a, (r[2], r[3])) and same(b, (r[0], r[1]))) for r in K.red):
                    continue
                na, nb = sum(1 for q in ends if same(q, a)) - 1, sum(1 for q in ends if same(q, b)) - 1
                if (na == 0) == (nb == 0):
                    continue                                   # cả hai đầu nối hoặc cả hai cụt: không phải khe cụt ở góc
                cor = a if na else b
                if not any(math.hypot(q[0] - cor[0], q[1] - cor[1]) <= 1.5 for q in gp):
                    rach.append(e0)
        else:
            rach = []
        if rach:
            add('Sai rạch Green', 'canhbao', '%d nét đỏ ngắn của DXF khách (≈ %s) bị chép thành LINE biên có một đầu cụt (%s) mà quanh góc không có rạch Green: đó là chỗ rạch ở góc lõm, vẽ rạch Green 3 entity (LINE, ARC R0.5, LINE) thay vì chép nét khách làm biên' % (len(rach), f(length(rach[0])), ', '.join('%s-%s' % (loc(h[1]), loc(h[2])) for h in rach[:4])), True)
    if any(x['muc'] == 'canhbao' and not x.get('khong_xet_flag') for x in res['khac_biet']) and not has1 and not noflag:
        add('Thiếu Flag', 'canhbao', 'Hình khác DXF khách nhưng mã không có Flag 1 ("%s")' % FLAG1)
    return res


def src_dxf(src):
    out = []
    for fn in sorted(os.listdir(src)):
        u = fn.upper()
        if u.endswith('.DXF') and not u.endswith('_ALL.DXF') and not re.match(r'26-\d{6}[TF]?\.DXF', u) and os.path.isfile(os.path.join(src, fn)):
            out.append(os.path.join(src, fn))
    return out


def run(path, src, only=None):
    parts = [(c, [e for e in es if e[0] not in ('B', 'G')], fl, any(e[0] == 'B' for e in es), [e for e in es if e[0] == 'G']) for c, es, fl in load_ai(path)]
    ks, errs = [], []
    for p in src_dxf(src):
        try:
            ks.append(Khach(p))
        except Exception as ex:
            errs.append('Không đọc được DXF khách %s: %s' % (os.path.basename(p), ex))
    out = {'file': os.path.basename(path), 'dxf_khach': [os.path.basename(k.path) for k in ks], 'loi_doc': errs, 'ket_qua': []}
    for code, part, flags, bent, greens in parts:
        if only and code not in only:
            continue
        if not ks:
            out['ket_qua'].append({'ma': code, 'kieu': 'không có DXF khách', 'khac_biet': []})
            continue
        nh = sum(1 for e in part if e[0] == 'C')
        best = None
        for K in ks:
            fit = best_fit(part, K)
            if fit and (best is None or fit[0] > best[1][0]):
                best = (K, fit)
        if best is None:
            out['ket_qua'].append({'ma': code, 'kieu': 'không đối chiếu được', 'khac_biet': []})
            continue
        K, fit = best
        so, hh = fit[1], fit[2]
        flat = so >= (0.9 if bent else 0.6)             # chi tiết uốn: hình trải hiếm khi trùng hình chiếu, chỉ so cụm lỗ
        if flat or (hh >= 2 and hh >= 0.5 * nh):
            out['ket_qua'].append(compare(code, part, flags, K, fit, flat, greens))
        else:
            out['ket_qua'].append({'ma': code, 'kieu': 'không đối chiếu được', 'khop_bien': round(so, 3), 'lo_trung_tam': '%d/%d' % (hh, nh),
                                   'ghi_chu': 'Không hình chiếu nào của DXF khách chồng khít hình AI (chi tiết uốn, DXF khác tỉ lệ, hoặc không có DXF của mã này)', 'khac_biet': []})
    return out


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('file')
    ap.add_argument('--src')
    ap.add_argument('--code')
    ap.add_argument('--json', action='store_true')
    a = ap.parse_args()
    try:
        out = run(a.file, a.src or os.path.dirname(os.path.abspath(a.file)), set(a.code.split(',')) if a.code else None)
    except Exception as ex:
        print('LỖI: %s' % ex)
        sys.exit(2)
    warn = sum(1 for r in out['ket_qua'] for x in r['khac_biet'] if x['muc'] == 'canhbao')
    if a.json:
        print(json.dumps(out, ensure_ascii=False, indent=1))
    else:
        print('=== doi_chieu_khach: %s, %d DXF khách ===' % (out['file'], len(out['dxf_khach'])))
        for m in out['loi_doc']:
            print(' ! ' + m)
        for r in out['ket_qua']:
            head = '%s: %s' % (r['ma'], r['kieu'])
            if r.get('file_khach'):
                head += ' | %s | %s | biên khớp %d%%, lỗ trùng tâm %s' % (r['file_khach'], r['phep_dat'], round(r['khop_bien'] * 100), r['lo_trung_tam'])
            print(head)
            if r.get('ghi_chu'):
                print('   - ' + r['ghi_chu'])
            for x in r['khac_biet']:
                print('   [%s] %s: %s' % ('CẢNH BÁO' if x['muc'] == 'canhbao' else 'THÔNG TIN', x['loai'], x['mo_ta']))
    sys.exit(1 if warn else 0)


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""dxf_check.py - kiểm tra DXF đầu ra của skill dxf-sheetmetal (file riêng 26-xxxxxx.dxf và file <đơn>_ALL.dxf).
Dùng: python3 dxf_check.py FILE.dxf [--template [--tpl Template.dxf]] [--mat SS|SUS|AL|CU --t 3.2]
       [--expect yeucau.csv] [--src THU_MUC_DON] [--order 064301,064302] [--mirror 064157:064158] [--single THU_MUC] [--png out.png] [--slot 20x5 ...]
expect.csv: code,X,Y[,mat,t] (X/Y của CAD依頼書). Mã thoát 1 nếu có LỖI.
Chi tiết chữ コ/U (hai cánh ngoài cùng bằng nhau): CẢNH BÁO nếu số lỗ/φ hai cánh khác nhau.
Rãnh/lỗ dài (2 LINE song song + 2 nửa tròn): in THÔNG TIN tổng dài x rộng; --slot NxM (lặp được, ghi chú 長穴): LỖI nếu hình có rãnh mà không rãnh nào khớp (sai số 0.01).
Mặc định chỉ kiểm hình dạng; so cấu trúc file với Template (CRLF, header, owner 6F, handle...) chỉ chạy khi có --template."""
import sys, re, math, argparse, os, unicodedata, subprocess
from collections import defaultdict
import ezdxf

TOL = 1e-3
SLOTS = []  # [(tổng dài, rộng)] từ --slot
OUT = {'LỖI': [], 'CẢNH BÁO': [], 'THÔNG TIN': []}
CNT = defaultdict(int)
def rep(lv, msg):
    CNT[msg] += 1
    if CNT[msg] == 1: OUT[lv].append(msg)
def E(m): rep('LỖI', m)
def W(m): rep('CẢNH BÁO', m)
def I(m): rep('THÔNG TIN', m)
def f(v): return ('%.3f' % v).rstrip('0').rstrip('.')
def P(p): return '(%s; %s)' % (f(p[0]), f(p[1]))

STD_FLAGS = ['Kích thước PDF và DXF khác nhau', 'Kích thước giữa các hình chiếu không khớp', 'Thiếu kích thước',
             'Kích thước và hình dạng không khớp', 'Ghi chú tay không đọc rõ', 'Kích thước ghi quá mờ',
             'Không rõ kích thước trong hay ngoài', 'Số lượng lỗ ghi không khớp', 'Số lượng bo R hoặc vát C',
             'Độ giãn viết tay khác bảng', 'Không chắc mặt nào là mặt ngoài',
             'Không chắc trên tấm có Kegaki hay không',
             # Flag 12-20 của dxf-sheetmetal mục 11.4 (bổ sung 17/11/2026: trước đây script chỉ biết 12 câu nên báo nhầm)
             'Khi trên tấm có hàn', 'Trên tấm có hàn', 'Cộng thêm lượng dư gia công', 'Tổng các kích thước trong chuỗi Dim khác',
             'Chân dim kích thước bị lệch', 'Thiếu độ giãn dài', 'Có bất kì lỗ tròn', 'Có lỗ tròn', 'Lỗ tròn nhỏ hơn 1/2',
             'Kích thước có dung sai', 'Góc nhọn quá bé', 'Gọc nhọn quá bé', 'Thiếu DXF khách']

PILOT = {}
for _th, _d in (('M3', 2.5), ('M3.5', 2.9), ('M4', 3.3), ('M5', 4.2), ('M6', 5), ('M7', 6), ('M8', 6.8), ('M10', 8.5), ('M12', 10.3)):
    PILOT.setdefault(round(_d, 2), []).append(_th)

# ---------- bảng laser (Quy_Tac_Laser.md mục 2) ----------
def laser_r(mat, t):
    if mat == 'SS': return 0.5 if t <= 5 else 2 if t <= 9 else None if t < 19 else 3
    if mat in ('SUS', 'AL'): return 0.5 if t <= 6 else None
    if mat == 'CU': return 0.5 if t <= 5 else None
def pierce_out(mat, t):
    # Piercing ngoai thang (Quy_Tac_Laser muc 2); None = piercing cong hoac khong ro
    if mat == 'SS': return 3 if t <= 3.2 else 6 if t <= 9 else 10 if t <= 16 else None
    if mat in ('SUS', 'AL'): return 6 if t <= 8 else 10 if t <= 16 else None
    if mat == 'CU': return 6
def min_hole(mat, t):
    if mat == 'SS': return t / 2 if t < 16 else t
    if mat == 'SUS': return t / 2 if t <= 14 else 10 if t < 20 else t
    if mat == 'AL': return 0.8 * t if t < 16 else t
    if mat == 'CU': return t / 2 if t <= 5 else t

# ---------- 1. cấu trúc file so với Template ----------
def split(path):
    raw = open(path, 'rb').read()
    try: s = raw.decode('cp932')
    except UnicodeDecodeError as e: E('Không decode được cp932: %s' % e); s = raw.decode('cp932', 'replace')
    if s.count('\n') != s.count('\r\n'):
        E('Có dòng kết thúc bằng LF, phải là CRLF (\\r\\n): file không ghi theo Template (mục 11.2 bước 7)')
        return s.replace('\r\n', '\n').split('\n')
    return s.split('\r\n')

def sec_idx(L):
    i = next(k for k in range(1, len(L)) if L[k] == 'ENTITIES' and L[k - 1].strip() == '2')
    return i, L.index('ENDSEC', i)

def check_structure(path, tpl):
    L, T = split(path), split(tpl)
    for k in range(0, len(L) - 1, 2):
        if not re.fullmatch(r'-?\d+', L[k].strip()):
            E('Dòng %d không phải mã nhóm số nguyên: %r (lệch cặp mã/giá trị)' % (k + 1, L[k])); break
    try: i, j = sec_idx(L); ti, tj = sec_idx(T)
    except (StopIteration, ValueError): E('Không tìm thấy mục ENTITIES/ENDSEC'); return None
    if L[j - 1].strip() != '0': E("Thiếu mã '  0' trước ENDSEC của ENTITIES (lỗi ghép L[j:] thay vì L[j-1:])")
    if L[j - 1:] != T[tj - 1:]:
        d = next((k for k, (a, b) in enumerate(zip(L[j - 1:], T[tj - 1:])) if a != b), None)
        E('Phần từ ENDSEC của ENTITIES đến hết file khác Template (dòng lệch đầu tiên ~%s)' % (j + d if d is not None else 'độ dài'))
    H, TH = L[:i + 1], T[:ti + 1]
    if len(H) != len(TH):
        E('Phần trước ENTITIES khác số dòng so với Template (%d / %d): có thêm/bớt header, bảng hoặc style' % (len(H), len(TH)))
    else:
        ok = set()
        def blk(name, n):
            k = H.index(name); ok.update(range(k, k + n))
        blk('$EXTMAX', 7); blk('$HANDSEED', 3)
        k = H.index('*Active'); m = k
        while H[m] != '  0' or m == k: m += 1
        ok.update(range(k - 30, m))
        k = H.index('Standard', H.index('AcDbTextStyleTableRecord')); m = k
        while H[m] != '  0': m += 1
        ok.update(range(k, m))
        bad = [k for k in range(len(H)) if H[k] != TH[k] and k not in ok]
        if bad: E('Ngoài ENTITIES khác Template ở dòng %s (chỉ được khác EXTMAX, HANDSEED, VPORT *Active, mã 3 của Standard)' % ', '.join(str(b + 1) for b in bad[:8]))
    k = H.index('Standard', H.index('AcDbTextStyleTableRecord')); m = k
    while H[m] != '  3': m += 1
    if H[m + 1].lower() != 'arial.ttf': E("Style Standard mã 3 = %r, phải là 'arial.ttf' (SHX txt hiện '?' thay dấu)" % H[m + 1])
    ent = L[i + 1:j - 1]; hs = []
    for k in range(0, len(ent) - 1, 2):
        c, v = int(ent[k]), ent[k + 1]
        if 10 <= c <= 59 and not re.fullmatch(r'-?\d+(\.\d+)?', v.strip()): E('Số sai định dạng trong ENTITIES: mã %d = %r (không dùng 1e-05, nan, inf)' % (c, v))
        if c == 5: hs.append(int(v, 16))
        if c == 330 and v != '6F': E('Entity có owner 330 = %s, phải là 6F' % v)
        if c == 1 and any(ord(ch) > 127 for ch in v): E('TEXT có ký tự ngoài ASCII %r: phải ghi dạng \\U+XXXX' % v[:30])
    seed = lambda X: int(X[X.index('$HANDSEED') + 2], 16)
    if len(set(hs)) != len(hs): E('Trùng handle entity')
    if hs:
        if min(hs) < seed(T): E('Handle entity %X nhỏ hơn HANDSEED của Template (%X): có thể trùng handle mẫu' % (min(hs), seed(T)))
        if seed(L) <= max(hs): E('$HANDSEED (%X) phải lớn hơn handle lớn nhất (%X)' % (seed(L), max(hs)))
    ex = L.index('$EXTMAX')
    return float(L[ex + 2]), float(L[ex + 4])

# ---------- 2. hình học ----------
def arc_pts(c, r, a0, a1):
    a1 = a1 if a1 > a0 else a1 + 360
    p = lambda a: (c[0] + r * math.cos(math.radians(a)), c[1] + r * math.sin(math.radians(a)))
    return p(a0), p(a1), [p(a) for a in range(int(a0 // 90 + 1) * 90, int(a1) + 1, 90) if a0 < a < a1]

class Seg:
    def __init__(s, e):
        s.e, s.t = e, e.dxftype()
        if s.t == 'LINE':
            s.p, s.q = tuple(e.dxf.start)[:2], tuple(e.dxf.end)[:2]; s.ext = []
        else:
            s.c, s.r = tuple(e.dxf.center)[:2], e.dxf.radius
            s.a0, s.a1 = e.dxf.start_angle % 360, e.dxf.end_angle % 360
            s.p, s.q, s.ext = arc_pts(s.c, s.r, s.a0, s.a1)
    def pts(s): return [s.p, s.q] + s.ext
    def trav(s, at_q):
        """hướng đi p→q tại p hoặc q"""
        if s.t == 'LINE': d = (s.q[0] - s.p[0], s.q[1] - s.p[1])
        else: a = math.radians(s.a1 if at_q else s.a0); d = (-math.sin(a), math.cos(a))
        n = math.hypot(*d) or 1
        return (d[0] / n, d[1] / n)
    def poly(s, n=8):
        if s.t == 'LINE': return [s.p, s.q]
        a1 = s.a1 if s.a1 > s.a0 else s.a1 + 360
        return [(s.c[0] + s.r * math.cos(math.radians(s.a0 + (a1 - s.a0) * k / n)), s.c[1] + s.r * math.sin(math.radians(s.a0 + (a1 - s.a0) * k / n))) for k in range(n + 1)]

def near(a, b, t=TOL * 2): return abs(a[0] - b[0]) < t and abs(a[1] - b[1]) < t

def loops(segs, where):
    reps, node, gap = [], defaultdict(list), []
    def kk(p):
        for r in reps:
            d = math.hypot(p[0] - r[0], p[1] - r[1])
            if d < 0.01:
                if d > 1e-6: gap.append((p, d))
                return r
        reps.append(p); return p
    for s in segs: node[kk(s.p)].append((s, True)); node[kk(s.q)].append((s, False))
    for p, d in gap[:3]: W('%s: đầu mút lệch %s mm tại %s (nối được nhưng nên làm khớp tuyệt đối)' % (where, f(d), P(p)))
    for k, v in node.items():
        if len(v) == 1: E('%s: hở biên tại %s (đầu mút LINE/ARC không nối)' % (where, P(k)))
        elif len(v) > 2: W('%s: %d đoạn chung 1 điểm %s (trùng/chồng nét)' % (where, len(v), P(k)))
    used, out = set(), []
    for s0 in segs:
        if id(s0) in used: continue
        lp, s, fwd = [], s0, True
        while s is not None and id(s) not in used:
            used.add(id(s)); lp.append((s, fwd))
            end = s.q if fwd else s.p
            nx = [(t, fp) for t, fp in node[kk(end)] if id(t) not in used]
            s, fwd = (nx[0][0], nx[0][1]) if nx else (None, True)
        out.append(lp)
    return out

def lpoly(lp):
    pts = []
    for s, fw in lp:
        q = s.poly(); pts += q if fw else q[::-1]
    return pts
def area(pts): return sum(pts[k - 1][0] * pts[k][1] - pts[k][0] * pts[k - 1][1] for k in range(len(pts))) / 2
def inside(pt, poly):
    x, y, c = pt[0], pt[1], False
    for k in range(len(poly)):
        (x1, y1), (x2, y2) = poly[k - 1], poly[k]
        if (y1 > y) != (y2 > y) and x < (x2 - x1) * (y - y1) / (y2 - y1) + x1: c = not c
    return c
def dseg(pt, a, b):
    vx, vy = b[0] - a[0], b[1] - a[1]; L2 = vx * vx + vy * vy or 1e-12
    u = max(0, min(1, ((pt[0] - a[0]) * vx + (pt[1] - a[1]) * vy) / L2))
    return math.hypot(a[0] + u * vx - pt[0], a[1] + u * vy - pt[1])
def on_poly(pt, poly, t=0.01): return any(dseg(pt, poly[k - 1], poly[k]) < t for k in range(len(poly)))
def overlap(a, b, c, d, t=0.01):
    """2 đoạn thẳng thẳng hàng và chồng lên nhau một khoảng > t"""
    if dseg(c, a, b) > t and dseg(d, a, b) > t: return False
    ux, uy = b[0] - a[0], b[1] - a[1]; L = math.hypot(ux, uy) or 1
    if abs(((d[0] - c[0]) * uy - (d[1] - c[1]) * ux) / L) > t: return False
    pr = sorted([((c[0] - a[0]) * ux + (c[1] - a[1]) * uy) / L, ((d[0] - a[0]) * ux + (d[1] - a[1]) * uy) / L])
    return min(L, pr[1]) - max(0, pr[0]) > t

def classify(e):
    t, col, lt = e.dxftype(), e.dxf.color, e.dxf.linetype.upper()
    if e.dxf.layer != '0': W('%s handle %s ở layer %r, phải là layer 0' % (t, e.dxf.handle, e.dxf.layer))
    if t == 'TEXT': return 'text'
    if t == 'POINT': return 'point'
    if t not in ('LINE', 'ARC', 'CIRCLE'): E('Entity %s (handle %s) không thuộc LINE/CIRCLE/ARC/POINT/TEXT' % (t, e.dxf.handle)); return None
    if lt == 'DASHED':
        if t != 'LINE' or col not in (256, 7): W('Nét DASHED trên %s màu %s: đường uốn chỉ là LINE trắng' % (t, col))
        return 'bend'
    if lt not in ('BYLAYER', 'CONTINUOUS'): W('%s handle %s dùng linetype %s' % (t, e.dxf.handle, lt))
    if col in (256, 7, 0): return 'hole' if t == 'CIRCLE' else 'cut'
    if col == 3: return 'green'
    if col == 1: return 'keg'
    E('%s handle %s màu %d không đúng quy ước (trắng, Green 3, Đỏ 1)' % (t, e.dxf.handle, col)); return None

def bbox(items):
    xs, ys = [], []
    for c, e in items:
        if c in ('cut', 'green', 'bend', 'keg') and e.dxftype() in ('LINE', 'ARC'):
            for p in Seg(e).pts(): xs.append(p[0]); ys.append(p[1])
        elif e.dxftype() == 'CIRCLE':
            x, y, r = e.dxf.center.x, e.dxf.center.y, e.dxf.radius; xs += [x - r, x + r]; ys += [y - r, y + r]
        elif c == 'point': xs.append(e.dxf.location.x); ys.append(e.dxf.location.y)
    return (min(xs), min(ys), max(xs), max(ys)) if xs else None

def sig(items, x0, y0, tf=lambda p: p):
    """chữ ký hình học (để so file riêng/ALL và cặp gương); tf: phép biến hình trên tọa độ đã chuẩn hóa"""
    S = []
    for c, e in items:
        if c == 'text': continue
        t = e.dxftype(); g = lambda p: tuple(round(v, 2) + 0.0 for v in tf((p[0] - x0, p[1] - y0)))
        if t == 'LINE': S.append((c, 'L') + tuple(sorted([g(e.dxf.start), g(e.dxf.end)])))
        elif t == 'CIRCLE': S.append((c, 'C', g(e.dxf.center), round(e.dxf.radius, 3)))
        elif t == 'ARC':
            s = Seg(e); S.append((c, 'A', g(s.c), round(s.r, 3)) + tuple(sorted([g(s.p), g(s.q)])))
        elif t == 'POINT': S.append((c, 'P', g(e.dxf.location)))
    return sorted(S)

def decode_u(s): return unicodedata.normalize('NFC', re.sub(r'\\U\+([0-9A-Fa-f]{4})', lambda m: chr(int(m.group(1), 16)), s))

# ---------- 3. kiểm từng hình ----------
def check_part(name, items, mat, t, is_all):
    segs = [Seg(e) for c, e in items if c == 'cut']
    if not segs:
        cs = sorted([e for c, e in items if c == 'hole'], key=lambda e: -e.dxf.radius)
        if not cs: E('%s: không có biên cắt' % name); return None
        o = cs[0]; items = [(('cut' if e is o else c), e) for c, e in items]
        x, y, r = o.dxf.center.x, o.dxf.center.y, o.dxf.radius
        if abs(x - r) > TOL: E('%s: phôi tròn φ%s, mép trái ở X = %s' % (name, f(2 * r), f(x - r)))
        I('%s: phôi tròn φ%s; lỗ %s; kegaki %d' % (name, f(2 * r), ', '.join('φ%s' % f(2 * e.dxf.radius) for e in cs[1:]) or '0', sum(1 for c, _ in items if c == 'keg')))
        return (x - r, y - r, x + r, y + r), 2 * r, 2 * r
    bb = bbox([(c, e) for c, e in items if c == 'cut'])
    Wd, Hd = bb[2] - bb[0], bb[3] - bb[1]
    lps = loops(segs, name)
    polys = [(lp, lpoly(lp)) for lp in lps]
    polys.sort(key=lambda x: -abs(area(x[1])))
    outer_lp, outer = polys[0]
    for lp, pg in polys[1:]:
        if not inside(pg[0], outer) and not on_poly(pg[0], outer): E('%s: vòng biên rời nằm ngoài biên ngoài tại %s (2 phôi trong 1 hình?)' % (name, P(pg[0])))
    ori = 1 if area(outer) > 0 else -1
    # góc trên biên ngoài
    sharp_cvx, sharp_ccv, radii = [], [], defaultdict(int)
    for k in range(len(outer_lp)):
        (a, fa), (b, fb) = outer_lp[k - 1], outer_lp[k]
        da = a.trav(True) if fa else tuple(-v for v in a.trav(False))
        db = b.trav(False) if fb else tuple(-v for v in b.trav(True))
        cr = da[0] * db[1] - da[1] * db[0]; dot = da[0] * db[0] + da[1] * db[1]
        turn = math.degrees(math.atan2(cr, dot))
        if abs(turn) < 1: continue
        inner = 180 - abs(turn); pt = b.p if fb else b.q
        if turn * ori > 0 and inner <= 91: sharp_cvx.append((pt, inner))
        elif turn * ori < 0: sharp_ccv.append((pt, 180 + abs(turn)))
        if a.t == 'ARC' and b.t == 'ARC' and near(a.c, b.c) and abs(a.r - b.r) < TOL: W('%s: 2 ARC liền nhau cùng tâm/bán kính tại %s, gộp thành 1' % (name, P(pt)))
    for lp, _ in polys:
        for s, _f in lp:
            if s.t == 'ARC': radii[round(s.r, 3)] += 1
    # rãnh/lỗ dài (đề xuất 068416-068417): vòng trong gồm 2 LINE song song bằng nhau + 2 ARC nửa tròn cùng R; in tổng dài = tâm-tâm + 2R
    slots = []
    for lp, _ in polys[1:]:
        ls, ac = [s for s, _f in lp if s.t == 'LINE'], [s for s, _f in lp if s.t == 'ARC']
        if len(lp) != 4 or len(ls) != 2: continue
        (A, B), (c1, c2) = ls, ac
        LA, LB = math.hypot(A.q[0] - A.p[0], A.q[1] - A.p[1]), math.hypot(B.q[0] - B.p[0], B.q[1] - B.p[1])
        if abs(LA - LB) > 0.01 or LA < 1e-6 or abs(c1.r - c2.r) > 0.01: continue
        if abs((A.q[0] - A.p[0]) * (B.q[1] - B.p[1]) - (A.q[1] - A.p[1]) * (B.q[0] - B.p[0])) / (LA * LB) > 1e-3: continue
        if any(abs(((s.a1 - s.a0) % 360) - 180) > 0.5 for s in (c1, c2)): continue
        if abs(math.hypot(c1.c[0] - c2.c[0], c1.c[1] - c2.c[1]) - LA) > 0.01: continue
        R = (c1.r + c2.r) / 2
        slots.append(((c1.c[0] + c2.c[0]) / 2, (c1.c[1] + c2.c[1]) / 2, LA + 2 * R, 2 * R, LA))
    for x, y, L, Wd_, D in slots: I('%s: rãnh tâm %s, tổng dài %s x rộng %s (tâm-tâm %s)' % (name, P((x, y)), f(L), f(Wd_), f(D)))
    if slots and SLOTS and not any(abs(L - n) < 0.01 and abs(Wd_ - m) < 0.01 for _x, _y, L, Wd_, _d in slots for n, m in SLOTS):
        E('%s: rãnh ghi %s nhưng DXF có %s' % (name, ' / '.join('%sx%s' % (f(n), f(m)) for n, m in SLOTS), ', '.join('%s x %s' % (f(L), f(Wd_)) for _x, _y, L, Wd_, _d in slots)))
    rexp = laser_r(mat, t) if mat else None
    if sharp_cvx:
        lst = ', '.join('%s %s°' % (P(p), f(a)) for p, a in sharp_cvx[:6])
        if mat and rexp is None: I('%s: %d góc lồi sắc (đúng vì %s t%s không bo): %s' % (name, len(sharp_cvx), mat, f(t), lst))
        else: E('%s: %d góc lồi ≤ 90° chưa bo%s: %s (trừ khi khách quy định không bo)' % (name, len(sharp_cvx), ' R%s' % f(rexp) if rexp else ' (thiếu --mat/--t)', lst))
    if mat == 'SS' and t >= 19 and sharp_ccv: E('%s: thép ≥19t phải bo R3 cả góc lõm, còn %d góc lõm sắc' % (name, len(sharp_ccv)))
    small = [r for r in radii if rexp and r < rexp - TOL]
    if small: I('%s: có cung R%s nhỏ hơn Laser R%s (hạ R vì góc quá nhỏ? phải nêu trong báo cáo)' % (name, '/R'.join(f(r) for r in small), f(rexp)))
    if mat and rexp is None and rexp != 3 and radii.get(0.5): W('%s: vật liệu %s t%s không bo laser nhưng có %d cung R0.5' % (name, mat, f(t), radii[0.5]))
    # lỗ
    holes = defaultdict(int); dmin = min_hole(mat, t) if mat else None
    pts_hole = []
    for c, e in items:
        if c == 'hole':
            ctr = (e.dxf.center.x, e.dxf.center.y); d = 2 * e.dxf.radius; holes[round(d, 3)] += 1
            if not inside(ctr, outer): E('%s: lỗ φ%s tâm %s nằm ngoài biên phôi' % (name, f(d), P(ctr)))
            if dmin and d < dmin - TOL: W('%s: lỗ φ%s < lỗ nhỏ nhất %s (%s t%s): phải là POINT, trừ quy định khách (vd 810)' % (name, f(d), f(dmin), mat, f(t)))
        if c == 'point':
            pt = (e.dxf.location.x, e.dxf.location.y)
            if not inside(pt, outer) and not on_poly(pt, outer): E('%s: POINT %s nằm ngoài phôi' % (name, P(pt)))
            jl = [(x.dxf.insert.x, x.dxf.insert.y) for k, x in items if k == 'text' and x.dxf.text in ('J', 'LJ')]
            if not any(abs(pt[0] - a) < 0.01 and abs(pt[1] - b) < 0.01 for a, b in jl): pts_hole.append(pt)
    if pts_hole and dmin:
        W('%s: %d POINT lỗ (%s): chỉ đúng khi lỗ gốc (kể cả lỗ mồi) < lỗ nhỏ nhất %s (%s t%s) hoặc ghi chú tay ピアス khoanh riêng quanh lỗ đó (tem PIERCING đầu trang không đủ); lỗ ren có lỗ mồi ≥ %s phải vẽ CIRCLE (lỗi 521030-12)' % (name, len(pts_hole), ', '.join(P(p) for p in pts_hole[:4]), f(dmin), mat, f(t), f(dmin)))
    # đường uốn
    bends = [Seg(e) for c, e in items if c == 'bend']
    cand = []
    for x in range(len(bends)):
        for y in range(x + 1, len(bends)):
            A, B = bends[x], bends[y]
            u = (A.q[0] - A.p[0], A.q[1] - A.p[1]); L = math.hypot(*u) or 1; v = (B.q[0] - B.p[0], B.q[1] - B.p[1])
            if abs(u[0] * v[1] - u[1] * v[0]) / (L * (math.hypot(*v) or 1)) > 1e-4: continue
            dist = abs((B.p[0] - A.p[0]) * u[1] - (B.p[1] - A.p[1]) * u[0]) / L
            pr = sorted([((B.p[0] - A.p[0]) * u[0] + (B.p[1] - A.p[1]) * u[1]) / L, ((B.q[0] - A.p[0]) * u[0] + (B.q[1] - A.p[1]) * u[1]) / L])
            if 0.05 < dist < 30 and min(L, pr[1]) - max(0, pr[0]) > 0.5 * min(L, pr[1] - pr[0]): cand.append((dist, x, y))
    paired, pairs = set(), []
    for dist, x, y in sorted(cand):
        if x not in paired and y not in paired: paired.update((x, y)); pairs.append((bends[x], bends[y], dist))
    for k, s in enumerate(bends):
        if k not in paired: W('%s: đường uốn %s→%s không có cặp (mỗi chỗ uốn 2 LINE DASHED cách nhau = độ giãn)' % (name, P(s.p), P(s.q)))
        mid = ((s.p[0] + s.q[0]) / 2, (s.p[1] + s.q[1]) / 2)
        if not inside(mid, outer): E('%s: đường uốn %s→%s nằm ngoài phôi' % (name, P(s.p), P(s.q)))
    # chi tiết chữ コ/U: hai cánh ngoài cùng bề rộng bằng nhau mà lỗ hai cánh khác nhau (đề xuất 066976, 26-067270)
    if len(pairs) >= 2:
        bor = {1 if abs(A.p[1] - A.q[1]) < TOL and abs(B.p[1] - B.q[1]) < TOL else 0 if abs(A.p[0] - A.q[0]) < TOL and abs(B.p[0] - B.q[0]) < TOL else None for A, B, _d in pairs}
        if len(bor) == 1 and None not in bor:
            cs = bor.pop()   # trục xếp cánh: 1 (Y) khi đường uốn song song X; 0 (X) khi song song Y
            lo = min(min(A.p[cs], B.p[cs]) for A, B, _d in pairs); hi = max(max(A.p[cs], B.p[cs]) for A, B, _d in pairs)
            w1, w2 = lo - bb[cs], bb[cs + 2] - hi
            if w1 > 1 and w2 > 1 and abs(w1 - w2) < 0.1:
                hc = [((e.dxf.center.x, e.dxf.center.y)[cs], round(2 * e.dxf.radius, 2)) for c, e in items if c == 'hole']
                hc += [(p[cs], 0) for p in pts_hole]
                h1, h2 = sorted(d for v, d in hc if bb[cs] < v < lo), sorted(d for v, d in hc if hi < v < bb[cs + 2])
                if h1 != h2:
                    W('%s: hai cánh ngoài cùng bằng nhau (%s mm) nhưng lỗ không đối xứng (%d lỗ %s so %d lỗ %s); chi tiết chữ コ mặc định mỗi cánh đủ lỗ (dxf-sheetmetal mục 10), kiểm lại ghi chú/bản vẽ, không có thì Flag' % (
                        name, f(w1), len(h1), '/'.join('φ%s' % f(d) for d in sorted(set(h1))) or '-', len(h2), '/'.join('φ%s' % f(d) for d in sorted(set(h2))) or '-'))
    # rạch Green
    gs = [Seg(e) for c, e in items if c == 'green']
    for s in gs:
        if s.t == 'ARC' and abs(s.r - 0.5) > TOL: W('%s: cung rạch Green R%s, chuẩn là R0.5' % (name, f(s.r)))
    pexp = pierce_out(mat, t) if mat else None
    for s in gs:
        if s.t != 'LINE': continue
        dx, dy = s.q[0] - s.p[0], s.q[1] - s.p[1]; Ls = math.hypot(dx, dy)
        if Ls < 1e-6: continue
        if abs(abs(dx) - abs(dy)) < 1e-3 * Ls:
            # LINE cheo 45: dai = (Piercing - 0.146) x sqrt2 (diem dau cach moi mep khoet = Piercing ngoai)
            pc = Ls / math.sqrt(2) + 0.5 - 0.5 / math.sqrt(2)
            if pexp and abs(pc - pexp) > 0.05:
                E('%s: rạch Green %s→%s: điểm đầu cách mép khoét %s, chuẩn = Piercing ngoài %s (%s t%s)' % (name, P(s.p), P(s.q), f(pc), f(pexp), mat, f(t)))
        elif t and (abs(dx) < 1e-6 or abs(dy) < 1e-6):
            dep = Ls + 0.5 * (math.sqrt(2) - 1)
            if abs(dep - (t + 0.2)) > 0.05:
                W('%s: rạch Green %s→%s sâu %s tính từ góc khoét, chuẩn t + 0.2 = %s' % (name, P(s.p), P(s.q), f(dep), f(t + 0.2)))
    ng = len(gs)
    if ng % 3: W('%s: %d entity Green, mỗi đường rạch chuẩn gồm 3 (LINE, ARC R0.5, LINE)' % (name, ng))
    nearb = lambda p: any(dseg(p, b.p, b.q) < 6 for b in bends)
    nog = [p for p, a in sharp_ccv if abs(a - 270) < 1 and nearb(p) and not any(min(math.hypot(p[0] - q[0], p[1] - q[1]) for q in s.pts()) < 1.2 for s in gs)]
    if nog: W('%s: %d góc lõm 90° sát đường uốn không có rạch Green: %s (vách–tấm/hộp phải rạch; ngoại lệ: hộp vát 135°, khoét relief, mép thân nằm giữa 2 đường uốn)' % (name, len(nog), ', '.join(P(p) for p in nog[:6])))
    # kegaki
    obl = [(s.p, s.q) for s in segs if s.t == 'LINE']; bl = [(s.p, s.q) for s in bends]
    nk = 0
    for c, e in items:
        if c != 'keg': continue
        nk += 1
        if e.dxftype() == 'LINE':
            p, q = tuple(e.dxf.start)[:2], tuple(e.dxf.end)[:2]
            mid = ((p[0] + q[0]) / 2, (p[1] + q[1]) / 2)
            if not inside(mid, outer) and not on_poly(mid, outer): E('%s: kegaki %s→%s nằm ngoài phôi' % (name, P(p), P(q)))
            if any(overlap(a, b, p, q) for a, b in obl): E('%s: kegaki %s→%s trùng mép phôi (phải bỏ)' % (name, P(p), P(q)))
            if any(overlap(a, b, p, q) for a, b in bl): E('%s: kegaki %s→%s trùng đường uốn (phải bỏ)' % (name, P(p), P(q)))
        elif e.dxftype() == 'ARC':
            # cung kegaki lớn (tâm có thể ở ngoài phôi): kiểm điểm đầu, giữa, cuối cung
            a0, a1 = e.dxf.start_angle, e.dxf.end_angle
            sw = (a1 - a0) % 360
            cx, cy, r = e.dxf.center.x, e.dxf.center.y, e.dxf.radius
            for k in (0.02, 0.5, 0.98):
                a = math.radians(a0 + sw * k); pt = (cx + r * math.cos(a), cy + r * math.sin(a))
                if not inside(pt, outer) and not on_poly(pt, outer):
                    E('%s: kegaki ARC nằm ngoài phôi' % name); break
        elif not inside((e.dxf.center.x, e.dxf.center.y), outer): E('%s: kegaki %s nằm ngoài phôi' % (name, e.dxftype()))
    # trùng nét, nét 0
    seen = set()
    for c, e in items:
        if c == 'text': continue
        s = tuple(sig([(c, e)], 0, 0))
        if s in seen: E('%s: entity trùng lặp %s' % (name, s[0][:3]))
        seen.add(s)
        if e.dxftype() == 'LINE' and near(e.dxf.start, e.dxf.end): E('%s: LINE dài 0 tại %s' % (name, P(e.dxf.start)))
    # áp trục, chiều dài theo X
    ax = any(s.t == 'LINE' and abs(s.p[1] - bb[1]) < TOL and abs(s.q[1] - bb[1]) < TOL for s in segs)
    ay = any(s.t == 'LINE' and abs(s.p[0] - bb[0]) < TOL and abs(s.q[0] - bb[0]) < TOL for s in segs)
    if not (ax and ay): W('%s: không có cạnh thẳng áp %s (chọn hướng có cạnh trên cả Ox và Oy, mục 10)' % (name, ' và '.join(n for n, ok in (('Ox', ax), ('Oy', ay)) if not ok)))
    if Hd > Wd + TOL: W('%s: cạnh dài hơn nằm theo Y (%s x %s), quy tắc: cạnh dài theo X' % (name, f(Wd), f(Hd)))
    # J/LJ phôi dài hẹp
    pts = [(e.dxf.location.x, e.dxf.location.y) for c, e in items if c == 'point' and abs(e.dxf.location.y - bb[3]) < TOL]
    if Hd <= 100 and Wd >= 1000:
        nJ = 1 if Wd <= 1500 else 2 if Wd <= 2000 else 3 if Wd <= 2500 else None
        if nJ:
            # đầu mép trên vát C (LINE chéo nối vào): tính 30 từ đầu đoạn thẳng (30/10/2026, 521030-09); đầu bo R giữ theo khung
            top = [q for q in segs if q.t == 'LINE' and abs(q.p[1] - bb[3]) < TOL and abs(q.q[1] - bb[3]) < TOL]
            x0, x1 = bb[0], bb[2]
            if top:
                tl, tr = min(min(q.p[0], q.q[0]) for q in top), max(max(q.p[0], q.q[0]) for q in top)
                def chamfer(xe):
                    return any(q.t == 'LINE' and abs(q.p[0] - q.q[0]) > TOL and abs(q.p[1] - q.q[1]) > TOL and (near(q.p, (xe, bb[3]), TOL) or near(q.q, (xe, bb[3]), TOL)) for q in segs)
                if chamfer(tl): x0 = tl
                if chamfer(tr): x1 = tr
            xs = [x0 + 30 + (x1 - x0 - 60) * k / nJ for k in range(nJ + 1)]
            miss = [x for x in xs if not any(abs(p[0] - x) < 0.01 for p in pts)]
            if miss: E('%s: phôi dài hẹp %s x %s cần %d J + 1 LJ trên mép trên, thiếu POINT tại x = %s' % (name, f(Wd), f(Hd), nJ, ', '.join(f(x - bb[0]) for x in miss)))
            tx = [(e.dxf.text, (e.dxf.insert.x, e.dxf.insert.y), e.dxf.height) for c, e in items if c == 'text' and e.dxf.text in ('J', 'LJ')]
            for k, x in enumerate(xs):
                want = 'LJ' if k == nJ else 'J'
                if not any(tt == want and near(p, (x, bb[3]), 0.01) and abs(h - 10) < TOL for tt, p, h in tx): E('%s: thiếu TEXT %s cao 10 tại %s' % (name, want, P((x, bb[3]))))
        else: W('%s: phôi dài %s > 2500, quy tắc J/LJ chưa có, hỏi người dùng' % (name, f(Wd)))
    elif pts and Hd > 100: W('%s: có POINT trên mép trên nhưng phôi không thuộc loại dài hẹp' % name)
    pil = ['%dxφ%s (%s)' % (n, f(d), '/'.join(PILOT[round(d, 2)])) for d, n in sorted(holes.items()) if round(d, 2) in PILOT]
    if pil: I('%s: lỗ trùng lỗ mồi taro theo bảng: %s; đối chiếu ghi chú tay 下穴 / lỗ mồi trong PDF (ghi chú tay thắng bảng, mục 7 dxf-sheetmetal)' % (name, ', '.join(pil)))
    I('%s: %s x %s | %d vòng biên, lỗ %s, cung %s, uốn %d cặp (giãn %s), Green %d, kegaki %d' % (
        name, f(Wd), f(Hd), len(lps), ', '.join('%dxφ%s' % (n, f(d)) for d, n in sorted(holes.items())) or '0',
        ', '.join('%dxR%s' % (n, f(r)) for r, n in sorted(radii.items())) or '0', len(pairs),
        '/'.join(sorted({f(d) for _, _, d in pairs})) or '-', ng, nk))
    return bb, Wd, Hd

# ---------- 4. chương trình chính ----------
# ---------- 4. đối chiếu nguồn: PDF bản vẽ + DXF khách (kỳ vọng dựng độc lập với file đang kiểm) ----------
NUM = r'(\d+(?:\.\d+)?)'
PILOT_D = {3: 2.5, 3.5: 2.9, 4: 3.3, 5: 4.2, 6: 5, 7: 6, 8: 6.8, 10: 8.5, 12: 10.3}
def norm_txt(s): return unicodedata.normalize('NFKC', s).translate({ord(c): 'φ' for c in 'ΦϕØø⌀∅Ф'})

def src_files(src):
    pdfs, dxfs = [], []
    for fn in sorted(os.listdir(src)):
        p, u = os.path.join(src, fn), fn.upper()
        if not os.path.isfile(p): continue
        if u.endswith('.PDF'): pdfs.append(p)
        elif u.endswith('.DXF') and not u.endswith('_ALL.DXF') and not re.match(r'26-\d{6}\.DXF', u): dxfs.append(p)
    return pdfs, dxfs

def pdf_pages(p):
    try: out = subprocess.run(['pdftotext', '-layout', p, '-'], capture_output=True, timeout=120).stdout.decode('utf-8', 'replace')
    except (OSError, subprocess.SubprocessError): return None
    return [norm_txt(x) for x in out.split('\f')[:-1]] or [norm_txt(out)]

def notes(txt):
    """ghi chú đọc được từ chữ PDF: n-φ, φ rời, taro M, 下穴, R, 展開, mã 6 số"""
    return {'hole': [(int(a), round(float(b), 2)) for a, b in re.findall(r'(\d+)\s*[-ー–]\s*φ\s*' + NUM, txt)],
            'phi': {round(float(x), 2) for x in re.findall(r'φ\s*' + NUM, txt)},
            'tap': {float(x) for x in re.findall(r'(?<![A-Za-z])M\s*' + NUM, txt)},
            'pilot': {round(float(x), 2) for x in re.findall(r'下穴\s*φ?\s*' + NUM, txt) + re.findall(r'(?<![A-Za-z\d.])' + NUM + r'\s*下穴', txt)},
            'R': {round(float(x), 2) for x in re.findall(r'(?<![A-Za-z])R\s*' + NUM, txt)},
            'dev': {round(float(x), 2) for x in re.findall(r'展開(?:長|寸法)?\s*[:：=]?\s*' + NUM, txt)},
            'codes': set(re.findall(r'(?<!\d)(0\d{5})(?!\d)', txt))}

def dxf_khach(p):
    """CIRCLE/ARC/khung bao của DXF khách (mở cả BLOCK/INSERT)"""
    circ, arcs, xs, ys = [], [], [], []
    def walk(ents, depth=0):
        for e in ents:
            t = e.dxftype()
            if t == 'INSERT' and depth < 4:
                try: walk(e.virtual_entities(), depth + 1)
                except Exception: pass
            elif t == 'CIRCLE':
                circ.append(round(2 * e.dxf.radius, 2)); r = e.dxf.radius
                xs.extend([e.dxf.center.x - r, e.dxf.center.x + r]); ys.extend([e.dxf.center.y - r, e.dxf.center.y + r])
            elif t == 'ARC': arcs.append(round(e.dxf.radius, 2))
            elif t == 'LINE': xs.extend([e.dxf.start.x, e.dxf.end.x]); ys.extend([e.dxf.start.y, e.dxf.end.y])
    walk(ezdxf.readfile(p).modelspace())
    return circ, arcs, ((max(xs) - min(xs), max(ys) - min(ys)) if xs else None)

def union(sets): return set().union(*sets) if sets else set()

def check_source(src, parts, mat_of):
    """parts: [y0, y1, items, tên, items, Wd, Hd]; mat_of(tên) -> (mat, t)"""
    pdfs, dxfs = src_files(src)
    if not pdfs and not dxfs:
        W('NGUỒN: không có PDF/DXF khách trong %s: chưa có kỳ vọng độc lập nên CHƯA kết luận được đúng/sai; stage thư mục đơn rồi chạy lại với --src' % src); return
    I('NGUỒN: %d PDF, %d DXF khách trong %s' % (len(pdfs), len(dxfs), src))
    pn = []   # (nơi, notes)
    for p in pdfs:
        pg = pdf_pages(p)
        if pg is None: W('NGUỒN: không chạy được pdftotext cho %s (cài poppler-utils); đọc PDF bằng tay' % os.path.basename(p)); continue
        scan = []
        for k, tx in enumerate(pg):
            if len(tx.strip()) < 20: scan.append(k + 1)
            else: pn.append(notes(tx))
        if scan: W('NGUỒN: %s trang %s không có lớp chữ (bản scan): đọc ảnh (pdftoppm -r 200) rồi tự dựng kỳ vọng: phôi, lỗ, 下穴, R, giãn, kegaki' % (os.path.basename(p), ','.join(map(str, scan))))
    dx = {}
    for p in dxfs:
        try: dx[p] = dxf_khach(p)
        except Exception as ex: W('NGUỒN: không đọc được DXF khách %s: %s' % (os.path.basename(p), ex)); continue
        c, a, bb = dx[p]
        I('NGUỒN: DXF khách %s: %d CIRCLE (φ %s), %d ARC, khung %s' % (os.path.basename(p), len(c), ', '.join(f(x) for x in sorted(set(c))[:12]) or '-', len(a), ('%s x %s' % (f(bb[0]), f(bb[1]))) if bb else '-'))
    drawn_all = set()
    for pt in parts:
        if len(pt) < 7: continue
        name, its, Wd, Hd = pt[3], pt[4], pt[5], pt[6]
        dr = defaultdict(int)
        for c, e in its:
            if c == 'hole': dr[round(2 * e.dxf.radius, 2)] += 1
        drawn_all |= set(dr)
        mine = [n for n in pn if name in n['codes']]
        mydx = [v for p, v in dx.items() if name in os.path.basename(p)]
        if pn and not mine: I('%s: không trang PDF nào có chữ mã này: chỉ so ở mức toàn đơn, tự đối chiếu theo hình' % name)
        pool = mine or pn
        pil, tap = union([n['pilot'] for n in pool]), union([n['tap'] for n in pool])
        pil_known = pil if mine else set()   # 下穴 chỉ áp lên hình khi trang PDF có đúng mã đó
        known = union([n['phi'] for n in pool]) | {round(PILOT_D[m], 2) for m in tap if m in PILOT_D} | pil
        for c, a, bb in (mydx or list(dx.values())): known |= set(c)
        for d, k in sorted(dr.items()):
            if d not in known: (W if mine or mydx else I)('%s: %d lỗ φ%s không có trong nguồn (PDF%s/DXF khách): sai φ hoặc lỗ thừa' % (name, k, f(d), '' if mine else ', toàn đơn - PDF không ghi mã nên chỉ để tham khảo'))
        for d in sorted(pil_known):
            if d not in dr: W('%s: PDF ghi 下穴φ%s nhưng hình không có lỗ φ%s (lỗi 064171: vẽ theo bảng lỗ mồi)' % (name, f(d), f(d)))
            else: I('%s: 下穴φ%s trong PDF khớp lỗ đã vẽ' % (name, f(d)))
        if pil_known:
            for d, k in dr.items():
                if d in PILOT and d not in pil: W('%s: %d lỗ φ%s (= lỗ mồi %s theo bảng) trong khi PDF có 下穴φ%s: ghi chú tay thắng bảng, đối chiếu từng nhóm' % (name, k, f(d), '/'.join(PILOT[d]), '/'.join(f(x) for x in sorted(pil))))
        if len(mine) == 1 and len(mine[0]['codes']) == 1:   # trang chỉ có 1 mã: đếm được
            tot = defaultdict(int)
            for k, d in mine[0]['hole']: tot[d] += k
            for d, k in sorted(tot.items()):
                if d not in pil and dr.get(d, 0) != k: W('%s: PDF ghi tổng %d-φ%s, hình có %d lỗ φ%s (đếm lại từng ghi chú; lỗ bị gạch thì bỏ qua)' % (name, k, f(d), dr.get(d, 0), f(d)))
        for x in sorted(union([n['dev'] for n in mine])):
            if not (abs(Wd - x) < 0.05 or abs(Hd - x) < 0.05): W('%s: PDF ghi 展開 %s, phôi %s x %s' % (name, f(x), f(Wd), f(Hd)))
        if mine:
            mt, t = mat_of(name); lr = laser_r(mt, t) if mt and t else None
            pr = union([n['R'] for n in mine]); arcs = {round(Seg(e).r, 2) for c, e in its if c == 'cut' and e.dxftype() == 'ARC'}
            miss = sorted(x for x in pr if x not in arcs and x != lr); extra = sorted(x for x in arcs if x not in pr and x != lr)
            if miss: I('%s: R trong PDF mà hình không có cung R đó: %s (R ở hình chiếu khác thì bỏ qua)' % (name, ', '.join(f(x) for x in miss)))
            if extra: I('%s: cung R trong hình mà PDF không ghi: %s (R lấy từ DXF khách/hạ R thì bỏ qua)' % (name, ', '.join(f(x) for x in extra)))
        for c, a, bb in mydx:
            if bb and not ((abs(Wd - bb[0]) < 0.1 and abs(Hd - bb[1]) < 0.1) or (abs(Wd - bb[1]) < 0.1 and abs(Hd - bb[0]) < 0.1)):
                I('%s: khung DXF khách %s x %s khác phôi %s x %s (phôi uốn/DXF nhiều hình thì bình thường; đối chiếu tay)' % (name, f(bb[0]), f(bb[1]), f(Wd), f(Hd)))
    want = {d for n in pn for k, d in n['hole'] if d not in union([x['pilot'] for x in pn])}
    for d in sorted(want - drawn_all): W('NGUỒN: PDF ghi n-φ%s nhưng không hình nào vẽ lỗ φ%s (lỗ gạch/lỗ ren thì bỏ qua, còn lại là thiếu lỗ)' % (f(d), f(d)))

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('file'); ap.add_argument('--tpl', default='/mnt/project-files/knowledge/Context_Laser/Template.dxf')
    ap.add_argument('--template', action='store_true', help='bật so cấu trúc file với Template (mặc định tắt, chỉ kiểm hình dạng)')
    ap.add_argument('--mat', choices=['SS', 'SUS', 'AL', 'CU']); ap.add_argument('--t', type=float)
    ap.add_argument('--expect'); ap.add_argument('--order'); ap.add_argument('--mirror', action='append', default=[])
    ap.add_argument('--single'); ap.add_argument('--png')
    ap.add_argument('--slot', action='append', default=[], help='rãnh ghi chú NxM (tổng dài x rộng), lặp được; LỖI nếu DXF có rãnh mà không rãnh nào khớp')
    ap.add_argument('--src', help='thư mục đơn chứa PDF bản vẽ/依頼 và DXF khách (mặc định: thư mục của FILE); đối chiếu kỳ vọng từ nguồn')
    a = ap.parse_args()
    for sl in a.slot:
        m = re.fullmatch(r'(\d+(?:\.\d+)?)\s*[xX×*]\s*(\d+(?:\.\d+)?)', sl.strip())
        if m: SLOTS.append((float(m.group(1)), float(m.group(2))))
        else: ap.error('--slot %r: dùng dạng NxM, ví dụ 20x5' % sl)
    is_all = a.file.upper().endswith('_ALL.DXF')
    exp = {}
    if a.expect:
        for ln in open(a.expect, encoding='utf-8-sig'):
            r = [x.strip() for x in ln.split(',')]
            if len(r) >= 3 and re.fullmatch(r'\d{6}', r[0]):
                exp[r[0]] = (float(r[1]), float(r[2]), r[3] if len(r) > 3 and r[3] else None, float(r[4]) if len(r) > 4 and r[4] else None)
    ext = None
    if a.template:
        if os.path.exists(a.tpl): ext = check_structure(a.file, a.tpl)
        else: W('Không tìm thấy Template %s: bỏ qua so cấu trúc' % a.tpl)
    try: doc = ezdxf.readfile(a.file)
    except Exception as ex:
        E('ezdxf không đọc được file: %s' % ex); doc = None
    if doc is None:
        for lv in ('LỖI', 'CẢNH BÁO'):
            for m in OUT[lv]: print('[%s] %s' % (lv, m))
        sys.exit(1)
    au = doc.audit()
    if au.errors: E('ezdxf audit: %d lỗi (%s)' % (len(au.errors), '; '.join(str(x.message) for x in au.errors[:3])))
    if au.fixes: W('ezdxf audit: %d chỗ tự sửa' % len(au.fixes))
    msp = doc.modelspace()
    items = [(c, e) for e in msp for c in [classify(e)] if c]
    geo = [(c, e) for c, e in items if c != 'text']
    # tách hình theo khoảng Y
    iv = sorted((((bbox([x])[1], bbox([x])[3]), x) for x in geo), key=lambda z: z[0])
    parts = []
    for (y0, y1), x in iv:
        if parts and y0 <= parts[-1][1] + 100: parts[-1][1] = max(parts[-1][1], y1); parts[-1][2].append(x)
        else: parts.append([y0, y1, [x]])
    parts.reverse()  # trên xuống dưới
    texts = [e for c, e in items if c == 'text']
    codes = [e for e in texts if re.fullmatch(r'\d{6}', e.dxf.text)]
    flags = [e for e in texts if e.dxf.color == 6]
    jl = [e for e in texts if e.dxf.text in ('J', 'LJ')]
    other = [e for e in texts if e not in codes and e not in flags and e not in jl]
    for e in other: W('TEXT lạ %r tại %s' % (decode_u(e.dxf.text)[:30], P(e.dxf.insert)))
    for e in texts:
        if e.dxf.style != 'Standard': E('TEXT %r dùng style %s, phải là Standard' % (e.dxf.text[:20], e.dxf.style))
    if not is_all and (codes or flags): E('File riêng không được có chữ mã / Flag (chỉ file ALL)')
    allbb, names, prev = [], [], None
    for k, (y0, y1, its) in enumerate(parts):
        its = its + [(c, e) for c, e in items if c == 'text' and e.dxf.text in ('J', 'LJ') and y0 - 1 <= e.dxf.insert.y <= y1 + 1]
        cd = [e for e in codes if y0 - 1 <= e.dxf.insert.y <= y1 + 1]
        name = cd[0].dxf.text if cd else ('hình %d' % (k + 1) if is_all else os.path.basename(a.file))
        if is_all and len(cd) != 1: E('%s (Y %s..%s): có %d chữ mã, cần đúng 1' % (name, f(y0), f(y1), len(cd)))
        mat, t = a.mat, a.t
        if name in exp and exp[name][2]: mat, t = exp[name][2], exp[name][3]
        r = check_part(name, its, mat, t, is_all)
        if not r: continue
        bb, Wd, Hd = r; allbb.append(bb); names.append(name)
        if abs(bb[0]) > TOL: (W if abs(bb[0]) < 5 else E)('%s: mép trái ở X = %s, phải là 0 (nếu do góc bo/vát: góc ảo trước khi bo đang ở 0?)' % (name, f(bb[0])))
        if not is_all and abs(bb[1]) > TOL: E('%s: góc dưới trái ở %s, phải là (0; 0)' % (name, P(bb[:2])))
        if is_all and cd:
            e = cd[0]; ym = bb[1] + Hd / 2
            if abs(e.dxf.insert.x + 150) > TOL: E('%s: chữ mã ở X = %s, phải là -150' % (name, f(e.dxf.insert.x)))
            if abs(e.dxf.insert.y - ym) > 0.05: W('%s: chữ mã ở Y = %s, phải = đáy + cao/2 = %s' % (name, f(e.dxf.insert.y), f(ym)))
            if abs(e.dxf.height - 12) > TOL: E('%s: chữ mã cao %s, phải là 12' % (name, f(e.dxf.height)))
            if e.dxf.color not in (256, 7): E('%s: chữ mã có màu %d' % (name, e.dxf.color))
            if e.dxf.halign or e.dxf.valign: E('%s: chữ mã không căn trái (halign/valign khác 0)' % name)
            # Flag
            fl = sorted([x for x in flags if abs(x.dxf.insert.x + 150) < 1 and x.dxf.insert.y < e.dxf.insert.y and x.dxf.insert.y > e.dxf.insert.y - 12 - 7 * 60], key=lambda x: -x.dxf.insert.y)
            fl = [x for x in fl if not any(c2 is not e and x.dxf.insert.y < c2.dxf.insert.y < e.dxf.insert.y for c2 in codes)]
            num, items_txt = 0, []
            for kk, x in enumerate(fl):
                if abs(x.dxf.insert.y - (e.dxf.insert.y - 12 - 7 * kk)) > 0.05: E('%s: dòng Flag %d ở Y = %s, phải = %s' % (name, kk + 1, f(x.dxf.insert.y), f(e.dxf.insert.y - 12 - 7 * kk)))
                if abs(x.dxf.height - 5) > TOL: E('%s: dòng Flag cao %s, phải là 5' % (name, f(x.dxf.height)))
                s = decode_u(x.dxf.text)
                if len(s) > 40: W('%s: dòng Flag dài %d ký tự (> 40): %r' % (name, len(s), s))
                if -150 + len(s) * 5 * 0.6 > -2: W('%s: dòng Flag có thể đè lên hình' % name)
                m = re.match(r'(\d+)\. ', s)
                if m:
                    num += 1
                    if int(m.group(1)) != num: E('%s: Flag đánh số %s, phải là %d' % (name, m.group(1), num))
                    items_txt.append(s[m.end():])
                elif not items_txt: E('%s: dòng Flag đầu không bắt đầu bằng "1. "' % name)
                else: items_txt[-1] += ' ' + s
                if s.lower().startswith('flag'): E('%s: không ghi chữ "Flag"' % name)
            for s in items_txt:
                if not any(s.startswith(x) for x in STD_FLAGS): W('%s: Flag %r không khớp câu chuẩn nào trong 20 trường hợp (dxf-sheetmetal mục 11.4)' % (name, s[:40]))
            if fl and k + 1 < len(parts) and fl[-1].dxf.insert.y - 4 < parts[k + 1][1] + 5: W('%s: Flag kéo xuống chạm hình bên dưới' % name)
            if fl: I('%s: %d Flag: %s' % (name, num, ' | '.join(items_txt)))
        if name in exp:
            X, Y = exp[name][:2]
            if not ((abs(Wd - X) < 0.05 and abs(Hd - Y) < 0.05) or (abs(Wd - Y) < 0.05 and abs(Hd - X) < 0.05)):
                W('%s: phôi %s x %s khác CAD依頼書 %s x %s (依頼 chỉ tham khảo: kiểm lại công thức giãn/chuỗi kích thước, Flag nếu đúng là lệch)' % (name, f(Wd), f(Hd), f(X), f(Y)))
            else: I('%s: khớp CAD依頼書 %s x %s' % (name, f(X), f(Y)))
        if prev is not None and is_all:
            gap = prev[1] - bb[3]
            if abs(gap - 200) > 0.01: W('%s: cách hình trên %s, chuẩn 200' % (name, f(gap)))
        prev = bb
        parts[k].append(name); parts[k].append(its); parts[k].extend([Wd, Hd])
    if is_all and allbb and abs(allbb[-1][1]) > TOL: E('Hình cuối không sát Y = 0 (đáy ở %s)' % f(allbb[-1][1]))
    if exp and is_all:
        miss = set(exp) - set(names)
        if miss: E('Thiếu mã so với danh sách 依頼: %s' % ', '.join(sorted(miss)))
    if a.order:
        want = [x.strip() for x in a.order.split(',')]
        if [n for n in names if n in want] != [n for n in want if n in names]: E('Thứ tự hình (trên xuống) %s khác thứ tự trang PDF %s' % (names, want))
    if ext and allbb:
        allx = [b[2] for b in allbb]; ally = [b[3] for b in allbb]
        if ext[0] < max(allx) - 0.01 or ext[1] < max(ally) - 0.01: W('$EXTMAX (%s; %s) nhỏ hơn khung bao hình (%s; %s)' % (f(ext[0]), f(ext[1]), f(max(allx)), f(max(ally))))
    byname = {p[3]: p for p in parts if len(p) > 4}
    def nsig(p, tf=lambda q: q):
        bb = bbox(p[4]); return sig(p[4], bb[0], bb[1], tf)
    for m in a.mirror:
        A, B = m.split(':')
        if A not in byname or B not in byname: E('Cặp gương %s: không thấy mã trong file' % m); continue
        pa, pb = byname[A], byname[B]; ba = bbox(pa[4]); w, h = ba[2] - ba[0], ba[3] - ba[1]
        sb = nsig(pb)
        tfs = {'giống hệt': lambda q: q, 'gương trái–phải': lambda q: (w - q[0], q[1]), 'gương trên–dưới': lambda q: (q[0], h - q[1]), 'xoay 180°': lambda q: (w - q[0], h - q[1])}
        hit = [k for k, tf in tfs.items() if sorted(nsig(pa, tf)) == sb]
        sym = sorted(nsig(pa, tfs['gương trái–phải'])) == nsig(pa) or sorted(nsig(pa, tfs['gương trên–dưới'])) == nsig(pa)
        if not hit: W('Cặp %s: %s không phải ảnh gương/xoay của %s, kiểm tay từng chi tiết (lỗ, kegaki, cánh)' % (m, B, A))
        elif any('gương' in x for x in hit): I('Cặp %s: %s là %s của %s' % (m, B, ' / '.join(hit), A))
        elif sym: I('Cặp %s: hình tự đối xứng nên bản 対称 giống bản 本図 (hợp lệ)' % m)
        else: E('Cặp %s: %s %s %s, KHÔNG phải ảnh gương (lỗi đã gặp 064157/158)' % (m, B, ' / '.join(hit), A))
    check_source(a.src or os.path.dirname(os.path.abspath(a.file)), parts, lambda n: (exp[n][2], exp[n][3]) if n in exp and exp[n][2] else (a.mat, a.t))
    if a.single and is_all:
        for n, p in byname.items():
            fp = os.path.join(a.single, '26-%s.dxf' % n)
            if not os.path.exists(fp): W('Không thấy file riêng %s' % fp); continue
            d2 = ezdxf.readfile(fp); its = [(c, e) for e in d2.modelspace() for c in [classify(e)] if c]
            b2 = bbox(its)
            if sig(its, b2[0], b2[1]) != nsig(p): E('%s: hình trong ALL khác file riêng 26-%s.dxf (ALL chỉ được tịnh tiến)' % (n, n))
            else: I('%s: khớp file riêng' % n)
    if a.png:
        try:
            import matplotlib; matplotlib.use('Agg'); import matplotlib.pyplot as plt
            from ezdxf.addons.drawing import RenderContext, Frontend
            from ezdxf.addons.drawing.matplotlib import MatplotlibBackend
            fig = plt.figure(figsize=(10, max(6, len(parts) * 3))); ax = fig.add_axes([0, 0, 1, 1])
            Frontend(RenderContext(doc), MatplotlibBackend(ax)).draw_layout(msp); fig.savefig(a.png, dpi=110, facecolor='black')
            I('Ảnh xem trước: %s' % a.png)
        except ImportError: W('Thiếu matplotlib (pip install matplotlib) để xuất --png')
    print('=== dxf_check: %s (%s, %d hình) ===' % (os.path.basename(a.file), 'file ALL' if is_all else 'file riêng', len(names)))
    for lv in ('LỖI', 'CẢNH BÁO', 'THÔNG TIN'):
        print('\n[%s] %d' % (lv, len(OUT[lv])))
        for m in OUT[lv]: print(' - ' + m + (' (x%d)' % CNT[m] if CNT[m] > 1 else ''))
    sys.exit(1 if OUT['LỖI'] else 0)

if __name__ == '__main__': main()

#!/usr/bin/env python3
"""dxf_check.py - kiểm tra DXF đầu ra của skill dxf-sheetmetal (file riêng 26-xxxxxx.dxf và file <đơn>_ALL.dxf).
Dùng: python3 dxf_check.py FILE.dxf [--template [--tpl Template.dxf]] [--mat SS|SUS|AL|CU --t 3.2]
       [--expect yeucau.csv] [--src THU_MUC_DON] [--order 064301,064302] [--mirror 064157:064158] [--single THU_MUC] [--png out.png] [--slot 20x5 ...]
expect.csv: code,X,Y[,mat,t] (X/Y của CAD依頼書). Mã thoát 1 nếu có LỖI.
Chi tiết chữ コ/U (hai cánh ngoài cùng bằng nhau): CẢNH BÁO nếu số lỗ/φ hai cánh khác nhau.
Rãnh/lỗ dài (2 LINE song song + 2 nửa tròn): in THÔNG TIN tổng dài x rộng; --slot NxM (lặp được, ghi chú 長穴): LỖI nếu hình có rãnh mà không rãnh nào khớp (sai số 0.01).
Mặc định chỉ kiểm hình dạng; so cấu trúc file với Template (CRLF, header, owner 6F, handle...) chỉ chạy khi có --template."""
import sys, re, math, argparse, os, unicodedata, subprocess
from collections import defaultdict
import ezdxf

TOL = 1e-3
SLOTS = []  # [(tổng dài, rộng)] từ --slot
OUT = {'LỖI': [], 'CẢNH BÁO': [], 'THÔNG TIN': []}
CNT = defaultdict(int)
def rep(lv, msg):
    CNT[msg] += 1
    if CNT[msg] == 1: OUT[lv].append(msg)
def E(m): rep('LỖI', m)
def W(m): rep('CẢNH BÁO', m)
def I(m): rep('THÔNG TIN', m)
def f(v): return ('%.3f' % v).rstrip('0').rstrip('.')
def P(p): return '(%s; %s)' % (f(p[0]), f(p[1]))

STD_FLAGS = ['Kích thước PDF và DXF khác nhau', 'Kích thước giữa các hình chiếu không khớp', 'Thiếu kích thước',
             'Kích thước và hình dạng không khớp', 'Ghi chú tay không đọc rõ', 'Kích thước ghi quá mờ',
             'Không rõ kích thước trong hay ngoài', 'Số lượng lỗ ghi không khớp', 'Số lượng bo R hoặc vát C',
             'Độ giãn viết tay khác bảng', 'Không chắc mặt nào là mặt ngoài',
             'Không chắc trên tấm có Kegaki hay không',
             # Flag 12-20 của dxf-sheetmetal mục 11.4 (bổ sung 17/11/2026: trước đây script chỉ biết 12 câu nên báo nhầm)
             'Khi trên tấm có hàn', 'Trên tấm có hàn', 'Cộng thêm lượng dư gia công', 'Tổng các kích thước trong chuỗi Dim khác',
             'Chân dim kích thước bị lệch', 'Thiếu độ giãn dài', 'Có bất kì lỗ tròn', 'Có lỗ tròn', 'Lỗ tròn nhỏ hơn 1/2',
             'Kích thước có dung sai', 'Góc nhọn quá bé', 'Gọc nhọn quá bé', 'Thiếu DXF khách']

PILOT = {}
for _th, _d in (('M3', 2.5), ('M3.5', 2.9), ('M4', 3.3), ('M5', 4.2), ('M6', 5), ('M7', 6), ('M8', 6.8), ('M10', 8.5), ('M12', 10.3)):
    PILOT.setdefault(round(_d, 2), []).append(_th)

# ---------- bảng laser (Quy_Tac_Laser.md mục 2) ----------
def laser_r(mat, t):
    if mat == 'SS': return 0.5 if t <= 5 else 2 if t <= 9 else None if t < 19 else 3
    if mat in ('SUS', 'AL'): return 0.5 if t <= 6 else None
    if mat == 'CU': return 0.5 if t <= 5 else None
def pierce_out(mat, t):
    # Piercing ngoai thang (Quy_Tac_Laser muc 2); None = piercing cong hoac khong ro
    if mat == 'SS': return 3 if t <= 3.2 else 6 if t <= 9 else 10 if t <= 16 else None
    if mat in ('SUS', 'AL'): return 6 if t <= 8 else 10 if t <= 16 else None
    if mat == 'CU': return 6
def min_hole(mat, t):
    if mat == 'SS': return t / 2 if t < 16 else t
    if mat == 'SUS': return t / 2 if t <= 14 else 10 if t < 20 else t
    if mat == 'AL': return 0.8 * t if t < 16 else t
    if mat == 'CU': return t / 2 if t <= 5 else t

# ---------- 1. cấu trúc file so với Template ----------
def split(path):
    raw = open(path, 'rb').read()
    try: s = raw.decode('cp932')
    except UnicodeDecodeError as e: E('Không decode được cp932: %s' % e); s = raw.decode('cp932', 'replace')
    if s.count('\n') != s.count('\r\n'):
        E('Có dòng kết thúc bằng LF, phải là CRLF (\\r\\n): file không ghi theo Template (mục 11.2 bước 7)')
        return s.replace('\r\n', '\n').split('\n')
    return s.split('\r\n')

def sec_idx(L):
    i = next(k for k in range(1, len(L)) if L[k] == 'ENTITIES' and L[k - 1].strip() == '2')
    return i, L.index('ENDSEC', i)

def check_structure(path, tpl):
    L, T = split(path), split(tpl)
    for k in range(0, len(L) - 1, 2):
        if not re.fullmatch(r'-?\d+', L[k].strip()):
            E('Dòng %d không phải mã nhóm số nguyên: %r (lệch cặp mã/giá trị)' % (k + 1, L[k])); break
    try: i, j = sec_idx(L); ti, tj = sec_idx(T)
    except (StopIteration, ValueError): E('Không tìm thấy mục ENTITIES/ENDSEC'); return None
    if L[j - 1].strip() != '0': E("Thiếu mã '  0' trước ENDSEC của ENTITIES (lỗi ghép L[j:] thay vì L[j-1:])")
    if L[j - 1:] != T[tj - 1:]:
        d = next((k for k, (a, b) in enumerate(zip(L[j - 1:], T[tj - 1:])) if a != b), None)
        E('Phần từ ENDSEC của ENTITIES đến hết file khác Template (dòng lệch đầu tiên ~%s)' % (j + d if d is not None else 'độ dài'))
    H, TH = L[:i + 1], T[:ti + 1]
    if len(H) != len(TH):
        E('Phần trước ENTITIES khác số dòng so với Template (%d / %d): có thêm/bớt header, bảng hoặc style' % (len(H), len(TH)))
    else:
        ok = set()
        def blk(name, n):
            k = H.index(name); ok.update(range(k, k + n))
        blk('$EXTMAX', 7); blk('$HANDSEED', 3)
        k = H.index('*Active'); m = k
        while H[m] != '  0' or m == k: m += 1
        ok.update(range(k - 30, m))
        k = H.index('Standard', H.index('AcDbTextStyleTableRecord')); m = k
        while H[m] != '  0': m += 1
        ok.update(range(k, m))
        bad = [k for k in range(len(H)) if H[k] != TH[k] and k not in ok]
        if bad: E('Ngoài ENTITIES khác Template ở dòng %s (chỉ được khác EXTMAX, HANDSEED, VPORT *Active, mã 3 của Standard)' % ', '.join(str(b + 1) for b in bad[:8]))
    k = H.index('Standard', H.index('AcDbTextStyleTableRecord')); m = k
    while H[m] != '  3': m += 1
    if H[m + 1].lower() != 'arial.ttf': E("Style Standard mã 3 = %r, phải là 'arial.ttf' (SHX txt hiện '?' thay dấu)" % H[m + 1])
    ent = L[i + 1:j - 1]; hs = []
    for k in range(0, len(ent) - 1, 2):
        c, v = int(ent[k]), ent[k + 1]
        if 10 <= c <= 59 and not re.fullmatch(r'-?\d+(\.\d+)?', v.strip()): E('Số sai định dạng trong ENTITIES: mã %d = %r (không dùng 1e-05, nan, inf)' % (c, v))
        if c == 5: hs.append(int(v, 16))
        if c == 330 and v != '6F': E('Entity có owner 330 = %s, phải là 6F' % v)
        if c == 1 and any(ord(ch) > 127 for ch in v): E('TEXT có ký tự ngoài ASCII %r: phải ghi dạng \\U+XXXX' % v[:30])
    seed = lambda X: int(X[X.index('$HANDSEED') + 2], 16)
    if len(set(hs)) != len(hs): E('Trùng handle entity')
    if hs:
        if min(hs) < seed(T): E('Handle entity %X nhỏ hơn HANDSEED của Template (%X): có thể trùng handle mẫu' % (min(hs), seed(T)))
        if seed(L) <= max(hs): E('$HANDSEED (%X) phải lớn hơn handle lớn nhất (%X)' % (seed(L), max(hs)))
    ex = L.index('$EXTMAX')
    return float(L[ex + 2]), float(L[ex + 4])

# ---------- 2. hình học ----------
def arc_pts(c, r, a0, a1):
    a1 = a1 if a1 > a0 else a1 + 360
    p = lambda a: (c[0] + r * math.cos(math.radians(a)), c[1] + r * math.sin(math.radians(a)))
    return p(a0), p(a1), [p(a) for a in range(int(a0 // 90 + 1) * 90, int(a1) + 1, 90) if a0 < a < a1]

class Seg:
    def __init__(s, e):
        s.e, s.t = e, e.dxftype()
        if s.t == 'LINE':
            s.p, s.q = tuple(e.dxf.start)[:2], tuple(e.dxf.end)[:2]; s.ext = []
        else:
            s.c, s.r = tuple(e.dxf.center)[:2], e.dxf.radius
            s.a0, s.a1 = e.dxf.start_angle % 360, e.dxf.end_angle % 360
            s.p, s.q, s.ext = arc_pts(s.c, s.r, s.a0, s.a1)
    def pts(s): return [s.p, s.q] + s.ext
    def trav(s, at_q):
        """hướng đi p→q tại p hoặc q"""
        if s.t == 'LINE': d = (s.q[0] - s.p[0], s.q[1] - s.p[1])
        else: a = math.radians(s.a1 if at_q else s.a0); d = (-math.sin(a), math.cos(a))
        n = math.hypot(*d) or 1
        return (d[0] / n, d[1] / n)
    def poly(s, n=8):
        if s.t == 'LINE': return [s.p, s.q]
        a1 = s.a1 if s.a1 > s.a0 else s.a1 + 360
        return [(s.c[0] + s.r * math.cos(math.radians(s.a0 + (a1 - s.a0) * k / n)), s.c[1] + s.r * math.sin(math.radians(s.a0 + (a1 - s.a0) * k / n))) for k in range(n + 1)]

def near(a, b, t=TOL * 2): return abs(a[0] - b[0]) < t and abs(a[1] - b[1]) < t

def loops(segs, where):
    reps, node, gap = [], defaultdict(list), []
    def kk(p):
        for r in reps:
            d = math.hypot(p[0] - r[0], p[1] - r[1])
            if d < 0.01:
                if d > 1e-6: gap.append((p, d))
                return r
        reps.append(p); return p
    for s in segs: node[kk(s.p)].append((s, True)); node[kk(s.q)].append((s, False))
    for p, d in gap[:3]: W('%s: đầu mút lệch %s mm tại %s (nối được nhưng nên làm khớp tuyệt đối)' % (where, f(d), P(p)))
    for k, v in node.items():
        if len(v) == 1: E('%s: hở biên tại %s (đầu mút LINE/ARC không nối)' % (where, P(k)))
        elif len(v) > 2: W('%s: %d đoạn chung 1 điểm %s (trùng/chồng nét)' % (where, len(v), P(k)))
    used, out = set(), []
    for s0 in segs:
        if id(s0) in used: continue
        lp, s, fwd = [], s0, True
        while s is not None and id(s) not in used:
            used.add(id(s)); lp.append((s, fwd))
            end = s.q if fwd else s.p
            nx = [(t, fp) for t, fp in node[kk(end)] if id(t) not in used]
            s, fwd = (nx[0][0], nx[0][1]) if nx else (None, True)
        out.append(lp)
    return out

def lpoly(lp):
    pts = []
    for s, fw in lp:
        q = s.poly(); pts += q if fw else q[::-1]
    return pts
def area(pts): return sum(pts[k - 1][0] * pts[k][1] - pts[k][0] * pts[k - 1][1] for k in range(len(pts))) / 2
def inside(pt, poly):
    x, y, c = pt[0], pt[1], False
    for k in range(len(poly)):
        (x1, y1), (x2, y2) = poly[k - 1], poly[k]
        if (y1 > y) != (y2 > y) and x < (x2 - x1) * (y - y1) / (y2 - y1) + x1: c = not c
    return c
def dseg(pt, a, b):
    vx, vy = b[0] - a[0], b[1] - a[1]; L2 = vx * vx + vy * vy or 1e-12
    u = max(0, min(1, ((pt[0] - a[0]) * vx + (pt[1] - a[1]) * vy) / L2))
    return math.hypot(a[0] + u * vx - pt[0], a[1] + u * vy - pt[1])
def on_poly(pt, poly, t=0.01): return any(dseg(pt, poly[k - 1], poly[k]) < t for k in range(len(poly)))
def overlap(a, b, c, d, t=0.01):
    """2 đoạn thẳng thẳng hàng và chồng lên nhau một khoảng > t"""
    if dseg(c, a, b) > t and dseg(d, a, b) > t: return False
    ux, uy = b[0] - a[0], b[1] - a[1]; L = math.hypot(ux, uy) or 1
    if abs(((d[0] - c[0]) * uy - (d[1] - c[1]) * ux) / L) > t: return False
    pr = sorted([((c[0] - a[0]) * ux + (c[1] - a[1]) * uy) / L, ((d[0] - a[0]) * ux + (d[1] - a[1]) * uy) / L])
    return min(L, pr[1]) - max(0, pr[0]) > t

def classify(e):
    t, col, lt = e.dxftype(), e.dxf.color, e.dxf.linetype.upper()
    if e.dxf.layer != '0': W('%s handle %s ở layer %r, phải là layer 0' % (t, e.dxf.handle, e.dxf.layer))
    if t == 'TEXT': return 'text'
    if t == 'POINT': return 'point'
    if t not in ('LINE', 'ARC', 'CIRCLE'): E('Entity %s (handle %s) không thuộc LINE/CIRCLE/ARC/POINT/TEXT' % (t, e.dxf.handle)); return None
    if lt == 'DASHED':
        if t != 'LINE' or col not in (256, 7): W('Nét DASHED trên %s màu %s: đường uốn chỉ là LINE trắng' % (t, col))
        return 'bend'
    if lt not in ('BYLAYER', 'CONTINUOUS'): W('%s handle %s dùng linetype %s' % (t, e.dxf.handle, lt))
    if col in (256, 7, 0): return 'hole' if t == 'CIRCLE' else 'cut'
    if col == 3: return 'green'
    if col == 1: return 'keg'
    E('%s handle %s màu %d không đúng quy ước (trắng, Green 3, Đỏ 1)' % (t, e.dxf.handle, col)); return None

def bbox(items):
    xs, ys = [], []
    for c, e in items:
        if c in ('cut', 'green', 'bend', 'keg') and e.dxftype() in ('LINE', 'ARC'):
            for p in Seg(e).pts(): xs.append(p[0]); ys.append(p[1])
        elif e.dxftype() == 'CIRCLE':
            x, y, r = e.dxf.center.x, e.dxf.center.y, e.dxf.radius; xs += [x - r, x + r]; ys += [y - r, y + r]
        elif c == 'point': xs.append(e.dxf.location.x); ys.append(e.dxf.location.y)
    return (min(xs), min(ys), max(xs), max(ys)) if xs else None

def sig(items, x0, y0, tf=lambda p: p):
    """chữ ký hình học (để so file riêng/ALL và cặp gương); tf: phép biến hình trên tọa độ đã chuẩn hóa"""
    S = []
    for c, e in items:
        if c == 'text': continue
        t = e.dxftype(); g = lambda p: tuple(round(v, 2) + 0.0 for v in tf((p[0] - x0, p[1] - y0)))
        if t == 'LINE': S.append((c, 'L') + tuple(sorted([g(e.dxf.start), g(e.dxf.end)])))
        elif t == 'CIRCLE': S.append((c, 'C', g(e.dxf.center), round(e.dxf.radius, 3)))
        elif t == 'ARC':
            s = Seg(e); S.append((c, 'A', g(s.c), round(s.r, 3)) + tuple(sorted([g(s.p), g(s.q)])))
        elif t == 'POINT': S.append((c, 'P', g(e.dxf.location)))
    return sorted(S)

def decode_u(s): return unicodedata.normalize('NFC', re.sub(r'\\U\+([0-9A-Fa-f]{4})', lambda m: chr(int(m.group(1), 16)), s))

# ---------- 3. kiểm từng hình ----------
def check_part(name, items, mat, t, is_all):
    segs = [Seg(e) for c, e in items if c == 'cut']
    if not segs:
        cs = sorted([e for c, e in items if c == 'hole'], key=lambda e: -e.dxf.radius)
        if not cs: E('%s: không có biên cắt' % name); return None
        o = cs[0]; items = [(('cut' if e is o else c), e) for c, e in items]
        x, y, r = o.dxf.center.x, o.dxf.center.y, o.dxf.radius
        if abs(x - r) > TOL: E('%s: phôi tròn φ%s, mép trái ở X = %s' % (name, f(2 * r), f(x - r)))
        I('%s: phôi tròn φ%s; lỗ %s; kegaki %d' % (name, f(2 * r), ', '.join('φ%s' % f(2 * e.dxf.radius) for e in cs[1:]) or '0', sum(1 for c, _ in items if c == 'keg')))
        return (x - r, y - r, x + r, y + r), 2 * r, 2 * r
    bb = bbox([(c, e) for c, e in items if c == 'cut'])
    Wd, Hd = bb[2] - bb[0], bb[3] - bb[1]
    lps = loops(segs, name)
    polys = [(lp, lpoly(lp)) for lp in lps]
    polys.sort(key=lambda x: -abs(area(x[1])))
    outer_lp, outer = polys[0]
    for lp, pg in polys[1:]:
        if not inside(pg[0], outer) and not on_poly(pg[0], outer): E('%s: vòng biên rời nằm ngoài biên ngoài tại %s (2 phôi trong 1 hình?)' % (name, P(pg[0])))
    ori = 1 if area(outer) > 0 else -1
    # góc trên biên ngoài
    sharp_cvx, sharp_ccv, radii = [], [], defaultdict(int)
    for k in range(len(outer_lp)):
        (a, fa), (b, fb) = outer_lp[k - 1], outer_lp[k]
        da = a.trav(True) if fa else tuple(-v for v in a.trav(False))
        db = b.trav(False) if fb else tuple(-v for v in b.trav(True))
        cr = da[0] * db[1] - da[1] * db[0]; dot = da[0] * db[0] + da[1] * db[1]
        turn = math.degrees(math.atan2(cr, dot))
        if abs(turn) < 1: continue
        inner = 180 - abs(turn); pt = b.p if fb else b.q
        if turn * ori > 0 and inner <= 91: sharp_cvx.append((pt, inner))
        elif turn * ori < 0: sharp_ccv.append((pt, 180 + abs(turn)))
        if a.t == 'ARC' and b.t == 'ARC' and near(a.c, b.c) and abs(a.r - b.r) < TOL: W('%s: 2 ARC liền nhau cùng tâm/bán kính tại %s, gộp thành 1' % (name, P(pt)))
    for lp, _ in polys:
        for s, _f in lp:
            if s.t == 'ARC': radii[round(s.r, 3)] += 1
    # rãnh/lỗ dài (đề xuất 068416-068417): vòng trong gồm 2 LINE song song bằng nhau + 2 ARC nửa tròn cùng R; in tổng dài = tâm-tâm + 2R
    slots = []
    for lp, _ in polys[1:]:
        ls, ac = [s for s, _f in lp if s.t == 'LINE'], [s for s, _f in lp if s.t == 'ARC']
        if len(lp) != 4 or len(ls) != 2: continue
        (A, B), (c1, c2) = ls, ac
        LA, LB = math.hypot(A.q[0] - A.p[0], A.q[1] - A.p[1]), math.hypot(B.q[0] - B.p[0], B.q[1] - B.p[1])
        if abs(LA - LB) > 0.01 or LA < 1e-6 or abs(c1.r - c2.r) > 0.01: continue
        if abs((A.q[0] - A.p[0]) * (B.q[1] - B.p[1]) - (A.q[1] - A.p[1]) * (B.q[0] - B.p[0])) / (LA * LB) > 1e-3: continue
        if any(abs(((s.a1 - s.a0) % 360) - 180) > 0.5 for s in (c1, c2)): continue
        if abs(math.hypot(c1.c[0] - c2.c[0], c1.c[1] - c2.c[1]) - LA) > 0.01: continue
        R = (c1.r + c2.r) / 2
        slots.append(((c1.c[0] + c2.c[0]) / 2, (c1.c[1] + c2.c[1]) / 2, LA + 2 * R, 2 * R, LA))
    for x, y, L, Wd_, D in slots: I('%s: rãnh tâm %s, tổng dài %s x rộng %s (tâm-tâm %s)' % (name, P((x, y)), f(L), f(Wd_), f(D)))
    if slots and SLOTS and not any(abs(L - n) < 0.01 and abs(Wd_ - m) < 0.01 for _x, _y, L, Wd_, _d in slots for n, m in SLOTS):
        E('%s: rãnh ghi %s nhưng DXF có %s' % (name, ' / '.join('%sx%s' % (f(n), f(m)) for n, m in SLOTS), ', '.join('%s x %s' % (f(L), f(Wd_)) for _x, _y, L, Wd_, _d in slots)))
    rexp = laser_r(mat, t) if mat else None
    if sharp_cvx:
        lst = ', '.join('%s %s°' % (P(p), f(a)) for p, a in sharp_cvx[:6])
        if mat and rexp is None: I('%s: %d góc lồi sắc (đúng vì %s t%s không bo): %s' % (name, len(sharp_cvx), mat, f(t), lst))
        else: E('%s: %d góc lồi ≤ 90° chưa bo%s: %s (trừ khi khách quy định không bo)' % (name, len(sharp_cvx), ' R%s' % f(rexp) if rexp else ' (thiếu --mat/--t)', lst))
    if mat == 'SS' and t >= 19 and sharp_ccv: E('%s: thép ≥19t phải bo R3 cả góc lõm, còn %d góc lõm sắc' % (name, len(sharp_ccv)))
    small = [r for r in radii if rexp and r < rexp - TOL]
    if small: I('%s: có cung R%s nhỏ hơn Laser R%s (hạ R vì góc quá nhỏ? phải nêu trong báo cáo)' % (name, '/R'.join(f(r) for r in small), f(rexp)))
    if mat and rexp is None and rexp != 3 and radii.get(0.5): W('%s: vật liệu %s t%s không bo laser nhưng có %d cung R0.5' % (name, mat, f(t), radii[0.5]))
    # lỗ
    holes = defaultdict(int); dmin = min_hole(mat, t) if mat else None
    pts_hole = []
    for c, e in items:
        if c == 'hole':
            ctr = (e.dxf.center.x, e.dxf.center.y); d = 2 * e.dxf.radius; holes[round(d, 3)] += 1
            if not inside(ctr, outer): E('%s: lỗ φ%s tâm %s nằm ngoài biên phôi' % (name, f(d), P(ctr)))
            if dmin and d < dmin - TOL: W('%s: lỗ φ%s < lỗ nhỏ nhất %s (%s t%s): phải là POINT, trừ quy định khách (vd 810)' % (name, f(d), f(dmin), mat, f(t)))
        if c == 'point':
            pt = (e.dxf.location.x, e.dxf.location.y)
            if not inside(pt, outer) and not on_poly(pt, outer): E('%s: POINT %s nằm ngoài phôi' % (name, P(pt)))
            jl = [(x.dxf.insert.x, x.dxf.insert.y) for k, x in items if k == 'text' and x.dxf.text in ('J', 'LJ')]
            if not any(abs(pt[0] - a) < 0.01 and abs(pt[1] - b) < 0.01 for a, b in jl): pts_hole.append(pt)
    if pts_hole and dmin:
        W('%s: %d POINT lỗ (%s): chỉ đúng khi lỗ gốc (kể cả lỗ mồi) < lỗ nhỏ nhất %s (%s t%s) hoặc ghi chú tay ピアス khoanh riêng quanh lỗ đó (tem PIERCING đầu trang không đủ); lỗ ren có lỗ mồi ≥ %s phải vẽ CIRCLE (lỗi 521030-12)' % (name, len(pts_hole), ', '.join(P(p) for p in pts_hole[:4]), f(dmin), mat, f(t), f(dmin)))
    # đường uốn
    bends = [Seg(e) for c, e in items if c == 'bend']
    cand = []
    for x in range(len(bends)):
        for y in range(x + 1, len(bends)):
            A, B = bends[x], bends[y]
            u = (A.q[0] - A.p[0], A.q[1] - A.p[1]); L = math.hypot(*u) or 1; v = (B.q[0] - B.p[0], B.q[1] - B.p[1])
            if abs(u[0] * v[1] - u[1] * v[0]) / (L * (math.hypot(*v) or 1)) > 1e-4: continue
            dist = abs((B.p[0] - A.p[0]) * u[1] - (B.p[1] - A.p[1]) * u[0]) / L
            pr = sorted([((B.p[0] - A.p[0]) * u[0] + (B.p[1] - A.p[1]) * u[1]) / L, ((B.q[0] - A.p[0]) * u[0] + (B.q[1] - A.p[1]) * u[1]) / L])
            if 0.05 < dist < 30 and min(L, pr[1]) - max(0, pr[0]) > 0.5 * min(L, pr[1] - pr[0]): cand.append((dist, x, y))
    paired, pairs = set(), []
    for dist, x, y in sorted(cand):
        if x not in paired and y not in paired: paired.update((x, y)); pairs.append((bends[x], bends[y], dist))
    for k, s in enumerate(bends):
        if k not in paired: W('%s: đường uốn %s→%s không có cặp (mỗi chỗ uốn 2 LINE DASHED cách nhau = độ giãn)' % (name, P(s.p), P(s.q)))
        mid = ((s.p[0] + s.q[0]) / 2, (s.p[1] + s.q[1]) / 2)
        if not inside(mid, outer): E('%s: đường uốn %s→%s nằm ngoài phôi' % (name, P(s.p), P(s.q)))
    # chi tiết chữ コ/U: hai cánh ngoài cùng bề rộng bằng nhau mà lỗ hai cánh khác nhau (đề xuất 066976, 26-067270)
    if len(pairs) >= 2:
        bor = {1 if abs(A.p[1] - A.q[1]) < TOL and abs(B.p[1] - B.q[1]) < TOL else 0 if abs(A.p[0] - A.q[0]) < TOL and abs(B.p[0] - B.q[0]) < TOL else None for A, B, _d in pairs}
        if len(bor) == 1 and None not in bor:
            cs = bor.pop()   # trục xếp cánh: 1 (Y) khi đường uốn song song X; 0 (X) khi song song Y
            lo = min(min(A.p[cs], B.p[cs]) for A, B, _d in pairs); hi = max(max(A.p[cs], B.p[cs]) for A, B, _d in pairs)
            w1, w2 = lo - bb[cs], bb[cs + 2] - hi
            if w1 > 1 and w2 > 1 and abs(w1 - w2) < 0.1:
                hc = [((e.dxf.center.x, e.dxf.center.y)[cs], round(2 * e.dxf.radius, 2)) for c, e in items if c == 'hole']
                hc += [(p[cs], 0) for p in pts_hole]
                h1, h2 = sorted(d for v, d in hc if bb[cs] < v < lo), sorted(d for v, d in hc if hi < v < bb[cs + 2])
                if h1 != h2:
                    W('%s: hai cánh ngoài cùng bằng nhau (%s mm) nhưng lỗ không đối xứng (%d lỗ %s so %d lỗ %s); chi tiết chữ コ mặc định mỗi cánh đủ lỗ (dxf-sheetmetal mục 10), kiểm lại ghi chú/bản vẽ, không có thì Flag' % (
                        name, f(w1), len(h1), '/'.join('φ%s' % f(d) for d in sorted(set(h1))) or '-', len(h2), '/'.join('φ%s' % f(d) for d in sorted(set(h2))) or '-'))
    # rạch Green
    gs = [Seg(e) for c, e in items if c == 'green']
    for s in gs:
        if s.t == 'ARC' and abs(s.r - 0.5) > TOL: W('%s: cung rạch Green R%s, chuẩn là R0.5' % (name, f(s.r)))
    pexp = pierce_out(mat, t) if mat else None
    for s in gs:
        if s.t != 'LINE': continue
        dx, dy = s.q[0] - s.p[0], s.q[1] - s.p[1]; Ls = math.hypot(dx, dy)
        if Ls < 1e-6: continue
        if abs(abs(dx) - abs(dy)) < 1e-3 * Ls:
            # LINE cheo 45: dai = (Piercing - 0.146) x sqrt2 (diem dau cach moi mep khoet = Piercing ngoai)
            pc = Ls / math.sqrt(2) + 0.5 - 0.5 / math.sqrt(2)
            if pexp and abs(pc - pexp) > 0.05:
                E('%s: rạch Green %s→%s: điểm đầu cách mép khoét %s, chuẩn = Piercing ngoài %s (%s t%s)' % (name, P(s.p), P(s.q), f(pc), f(pexp), mat, f(t)))
        elif t and (abs(dx) < 1e-6 or abs(dy) < 1e-6):
            dep = Ls + 0.5 * (math.sqrt(2) - 1)
            if abs(dep - (t + 0.2)) > 0.05:
                W('%s: rạch Green %s→%s sâu %s tính từ góc khoét, chuẩn t + 0.2 = %s' % (name, P(s.p), P(s.q), f(dep), f(t + 0.2)))
    ng = len(gs)
    if ng % 3: W('%s: %d entity Green, mỗi đường rạch chuẩn gồm 3 (LINE, ARC R0.5, LINE)' % (name, ng))
    nearb = lambda p: any(dseg(p, b.p, b.q) < 6 for b in bends)
    nog = [p for p, a in sharp_ccv if abs(a - 270) < 1 and nearb(p) and not any(min(math.hypot(p[0] - q[0], p[1] - q[1]) for q in s.pts()) < 1.2 for s in gs)]
    if nog: W('%s: %d góc lõm 90° sát đường uốn không có rạch Green: %s (vách–tấm/hộp phải rạch; ngoại lệ: hộp vát 135°, khoét relief, mép thân nằm giữa 2 đường uốn)' % (name, len(nog), ', '.join(P(p) for p in nog[:6])))
    # khe cụt (đề xuất 071234): LINE biên ngắn ≤ 2t có một đầu nối biên, đầu kia cụt (không chạm biên/Green nào) = nét khách ở góc lõm bị chép làm biên
    if t:
        cp = [q for s in segs for q in (s.p, s.q)]; gpt = [q for s in gs for q in s.pts()]
        for s in segs:
            Ls = math.hypot(s.q[0] - s.p[0], s.q[1] - s.p[1])
            if s.t != 'LINE' or Ls < 0.05 or Ls > 2 * t + TOL: continue
            na, nb = sum(1 for q in cp if near(q, s.p, 0.01)) - 1, sum(1 for q in cp if near(q, s.q, 0.01)) - 1
            if (na == 0) == (nb == 0): continue
            free = s.p if na == 0 else s.q
            if not any(near(q, free, 0.01) for q in gpt):
                E('%s: khe cụt %s→%s dài %s (≤ 2t) có một đầu cụt tại %s: nét ngắn của khách ở góc lõm là chỗ rạch Green, thay bằng rạch Green 3 entity (LINE, ARC R0.5, LINE), không chép làm LINE biên' % (name, P(s.p), P(s.q), f(Ls), P(free)))
    # kegaki
    obl =[(s.p, s.q) for s in segs if s.t == 'LINE']; bl = [(s.p, s.q) for s in bends]
    nk = 0
    for c, e in items:
        if c != 'keg': continue
        nk += 1
        if e.dxftype() == 'LINE':
            p, q = tuple(e.dxf.start)[:2], tuple(e.dxf.end)[:2]
            mid = ((p[0] + q[0]) / 2, (p[1] + q[1]) / 2)
            if not inside(mid, outer) and not on_poly(mid, outer): E('%s: kegaki %s→%s nằm ngoài phôi' % (name, P(p), P(q)))
            if any(overlap(a, b, p, q) for a, b in obl): E('%s: kegaki %s→%s trùng mép phôi (phải bỏ)' % (name, P(p), P(q)))
            if any(overlap(a, b, p, q) for a, b in bl): E('%s: kegaki %s→%s trùng đường uốn (phải bỏ)' % (name, P(p), P(q)))
        elif e.dxftype() == 'ARC':
            # cung kegaki lớn (tâm có thể ở ngoài phôi): kiểm điểm đầu, giữa, cuối cung
            a0, a1 = e.dxf.start_angle, e.dxf.end_angle
            sw = (a1 - a0) % 360
            cx, cy, r = e.dxf.center.x, e.dxf.center.y, e.dxf.radius
            for k in (0.02, 0.5, 0.98):
                a = math.radians(a0 + sw * k); pt = (cx + r * math.cos(a), cy + r * math.sin(a))
                if not inside(pt, outer) and not on_poly(pt, outer):
                    E('%s: kegaki ARC nằm ngoài phôi' % name); break
        elif not inside((e.dxf.center.x, e.dxf.center.y), outer): E('%s: kegaki %s nằm ngoài phôi' % (name, e.dxftype()))
    # trùng nét, nét 0
    seen = set()
    for c, e in items:
        if c == 'text': continue
        s = tuple(sig([(c, e)], 0, 0))
        if s in seen: E('%s: entity trùng lặp %s' % (name, s[0][:3]))
        seen.add(s)
        if e.dxftype() == 'LINE' and near(e.dxf.start, e.dxf.end): E('%s: LINE dài 0 tại %s' % (name, P(e.dxf.start)))
    # áp trục, chiều dài theo X
    ax = any(s.t == 'LINE' and abs(s.p[1] - bb[1]) < TOL and abs(s.q[1] - bb[1]) < TOL for s in segs)
    ay = any(s.t == 'LINE' and abs(s.p[0] - bb[0]) < TOL and abs(s.q[0] - bb[0]) < TOL for s in segs)
    if not (ax and ay): W('%s: không có cạnh thẳng áp %s (chọn hướng có cạnh trên cả Ox và Oy, mục 10)' % (name, ' và '.join(n for n, ok in (('Ox', ax), ('Oy', ay)) if not ok)))
    if Hd > Wd + TOL: W('%s: cạnh dài hơn nằm theo Y (%s x %s), quy tắc: cạnh dài theo X' % (name, f(Wd), f(Hd)))
    # J/LJ phôi dài hẹp
    pts = [(e.dxf.location.x, e.dxf.location.y) for c, e in items if c == 'point' and abs(e.dxf.location.y - bb[3]) < TOL]
    if Hd <= 100 and Wd >= 1000:
        nJ = 1 if Wd <= 1500 else 2 if Wd <= 2000 else 3 if Wd <= 2500 else None
        if nJ:
            # đầu mép trên vát C (LINE chéo nối vào): tính 30 từ đầu đoạn thẳng (30/10/2026, 521030-09); đầu bo R giữ theo khung
            top = [q for q in segs if q.t == 'LINE' and abs(q.p[1] - bb[3]) < TOL and abs(q.q[1] - bb[3]) < TOL]
            x0, x1 = bb[0], bb[2]
            if top:
                tl, tr = min(min(q.p[0], q.q[0]) for q in top), max(max(q.p[0], q.q[0]) for q in top)
                def chamfer(xe):
                    return any(q.t == 'LINE' and abs(q.p[0] - q.q[0]) > TOL and abs(q.p[1] - q.q[1]) > TOL and (near(q.p, (xe, bb[3]), TOL) or near(q.q, (xe, bb[3]), TOL)) for q in segs)
                if chamfer(tl): x0 = tl
                if chamfer(tr): x1 = tr
            xs = [x0 + 30 + (x1 - x0 - 60) * k / nJ for k in range(nJ + 1)]
            miss = [x for x in xs if not any(abs(p[0] - x) < 0.01 for p in pts)]
            if miss: E('%s: phôi dài hẹp %s x %s cần %d J + 1 LJ trên mép trên, thiếu POINT tại x = %s' % (name, f(Wd), f(Hd), nJ, ', '.join(f(x - bb[0]) for x in miss)))
            tx = [(e.dxf.text, (e.dxf.insert.x, e.dxf.insert.y), e.dxf.height) for c, e in items if c == 'text' and e.dxf.text in ('J', 'LJ')]
            for k, x in enumerate(xs):
                want = 'LJ' if k == nJ else 'J'
                if not any(tt == want and near(p, (x, bb[3]), 0.01) and abs(h - 10) < TOL for tt, p, h in tx): E('%s: thiếu TEXT %s cao 10 tại %s' % (name, want, P((x, bb[3]))))
        else: W('%s: phôi dài %s > 2500, quy tắc J/LJ chưa có, hỏi người dùng' % (name, f(Wd)))
    elif pts and Hd > 100: W('%s: có POINT trên mép trên nhưng phôi không thuộc loại dài hẹp' % name)
    pil = ['%dxφ%s (%s)' % (n, f(d), '/'.join(PILOT[round(d, 2)])) for d, n in sorted(holes.items()) if round(d, 2) in PILOT]
    if pil: I('%s: lỗ trùng lỗ mồi taro theo bảng: %s; đối chiếu ghi chú tay 下穴 / lỗ mồi trong PDF (ghi chú tay thắng bảng, mục 7 dxf-sheetmetal)' % (name, ', '.join(pil)))
    I('%s: %s x %s | %d vòng biên, lỗ %s, cung %s, uốn %d cặp (giãn %s), Green %d, kegaki %d' % (
        name, f(Wd), f(Hd), len(lps), ', '.join('%dxφ%s' % (n, f(d)) for d, n in sorted(holes.items())) or '0',
        ', '.join('%dxR%s' % (n, f(r)) for r, n in sorted(radii.items())) or '0', len(pairs),
        '/'.join(sorted({f(d) for _, _, d in pairs})) or '-', ng, nk))
    return bb, Wd, Hd

# ---------- 4. chương trình chính ----------
# ---------- 4. đối chiếu nguồn: PDF bản vẽ + DXF khách (kỳ vọng dựng độc lập với file đang kiểm) ----------
NUM = r'(\d+(?:\.\d+)?)'
PILOT_D = {3: 2.5, 3.5: 2.9, 4: 3.3, 5: 4.2, 6: 5, 7: 6, 8: 6.8, 10: 8.5, 12: 10.3}
def norm_txt(s): return unicodedata.normalize('NFKC', s).translate({ord(c): 'φ' for c in 'ΦϕØø⌀∅Ф'})

def src_files(src):
    pdfs, dxfs = [], []
    for fn in sorted(os.listdir(src)):
        p, u = os.path.join(src, fn), fn.upper()
        if not os.path.isfile(p): continue
        if u.endswith('.PDF'): pdfs.append(p)
        elif u.endswith('.DXF') and not u.endswith('_ALL.DXF') and not re.match(r'26-\d{6}\.DXF', u): dxfs.append(p)
    return pdfs, dxfs

def pdf_pages(p):
    try: out = subprocess.run(['pdftotext', '-layout', p, '-'], capture_output=True, timeout=120).stdout.decode('utf-8', 'replace')
    except (OSError, subprocess.SubprocessError): return None
    return [norm_txt(x) for x in out.split('\f')[:-1]] or [norm_txt(out)]

def notes(txt):
    """ghi chú đọc được từ chữ PDF: n-φ, φ rời, taro M, 下穴, R, 展開, mã 6 số"""
    return {'hole': [(int(a), round(float(b), 2)) for a, b in re.findall(r'(\d+)\s*[-ー–]\s*φ\s*' + NUM, txt)],
            'phi': {round(float(x), 2) for x in re.findall(r'φ\s*' + NUM, txt)},
            'tap': {float(x) for x in re.findall(r'(?<![A-Za-z])M\s*' + NUM, txt)},
            'pilot': {round(float(x), 2) for x in re.findall(r'下穴\s*φ?\s*' + NUM, txt) + re.findall(r'(?<![A-Za-z\d.])' + NUM + r'\s*下穴', txt)},
            'R': {round(float(x), 2) for x in re.findall(r'(?<![A-Za-z])R\s*' + NUM, txt)},
            'dev': {round(float(x), 2) for x in re.findall(r'展開(?:長|寸法)?\s*[:：=]?\s*' + NUM, txt)},
            'codes': set(re.findall(r'(?<!\d)(0\d{5})(?!\d)', txt))}

def dxf_khach(p):
    """CIRCLE/ARC/khung bao của DXF khách (mở cả BLOCK/INSERT)"""
    circ, arcs, xs, ys = [], [], [], []
    def walk(ents, depth=0):
        for e in ents:
            t = e.dxftype()
            if t == 'INSERT' and depth < 4:
                try: walk(e.virtual_entities(), depth + 1)
                except Exception: pass
            elif t == 'CIRCLE':
                circ.append(round(2 * e.dxf.radius, 2)); r = e.dxf.radius
                xs.extend([e.dxf.center.x - r, e.dxf.center.x + r]); ys.extend([e.dxf.center.y - r, e.dxf.center.y + r])
            elif t == 'ARC': arcs.append(round(e.dxf.radius, 2))
            elif t == 'LINE': xs.extend([e.dxf.start.x, e.dxf.end.x]); ys.extend([e.dxf.start.y, e.dxf.end.y])
    walk(ezdxf.readfile(p).modelspace())
    return circ, arcs, ((max(xs) - min(xs), max(ys) - min(ys)) if xs else None)

def union(sets): return set().union(*sets) if sets else set()

def check_source(src, parts, mat_of):
    """parts: [y0, y1, items, tên, items, Wd, Hd]; mat_of(tên) -> (mat, t)"""
    pdfs, dxfs = src_files(src)
    if not pdfs and not dxfs:
        W('NGUỒN: không có PDF/DXF khách trong %s: chưa có kỳ vọng độc lập nên CHƯA kết luận được đúng/sai; stage thư mục đơn rồi chạy lại với --src' % src); return
    I('NGUỒN: %d PDF, %d DXF khách trong %s' % (len(pdfs), len(dxfs), src))
    pn = []   # (nơi, notes)
    for p in pdfs:
        pg = pdf_pages(p)
        if pg is None: W('NGUỒN: không chạy được pdftotext cho %s (cài poppler-utils); đọc PDF bằng tay' % os.path.basename(p)); continue
        scan = []
        for k, tx in enumerate(pg):
            if len(tx.strip()) < 20: scan.append(k + 1)
            else: pn.append(notes(tx))
        if scan: W('NGUỒN: %s trang %s không có lớp chữ (bản scan): đọc ảnh (pdftoppm -r 200) rồi tự dựng kỳ vọng: phôi, lỗ, 下穴, R, giãn, kegaki' % (os.path.basename(p), ','.join(map(str, scan))))
    dx = {}
    for p in dxfs:
        try: dx[p] = dxf_khach(p)
        except Exception as ex: W('NGUỒN: không đọc được DXF khách %s: %s' % (os.path.basename(p), ex)); continue
        c, a, bb = dx[p]
        I('NGUỒN: DXF khách %s: %d CIRCLE (φ %s), %d ARC, khung %s' % (os.path.basename(p), len(c), ', '.join(f(x) for x in sorted(set(c))[:12]) or '-', len(a), ('%s x %s' % (f(bb[0]), f(bb[1]))) if bb else '-'))
    drawn_all = set()
    for pt in parts:
        if len(pt) < 7: continue
        name, its, Wd, Hd = pt[3], pt[4], pt[5], pt[6]
        dr = defaultdict(int)
        for c, e in its:
            if c == 'hole': dr[round(2 * e.dxf.radius, 2)] += 1
        drawn_all |= set(dr)
        mine = [n for n in pn if name in n['codes']]
        mydx = [v for p, v in dx.items() if name in os.path.basename(p)]
        if pn and not mine: I('%s: không trang PDF nào có chữ mã này: chỉ so ở mức toàn đơn, tự đối chiếu theo hình' % name)
        pool = mine or pn
        pil, tap = union([n['pilot'] for n in pool]), union([n['tap'] for n in pool])
        pil_known = pil if mine else set()   # 下穴 chỉ áp lên hình khi trang PDF có đúng mã đó
        known = union([n['phi'] for n in pool]) | {round(PILOT_D[m], 2) for m in tap if m in PILOT_D} | pil
        for c, a, bb in (mydx or list(dx.values())): known |= set(c)
        for d, k in sorted(dr.items()):
            if d not in known: (W if mine or mydx else I)('%s: %d lỗ φ%s không có trong nguồn (PDF%s/DXF khách): sai φ hoặc lỗ thừa' % (name, k, f(d), '' if mine else ', toàn đơn - PDF không ghi mã nên chỉ để tham khảo'))
        for d in sorted(pil_known):
            if d not in dr: W('%s: PDF ghi 下穴φ%s nhưng hình không có lỗ φ%s (lỗi 064171: vẽ theo bảng lỗ mồi)' % (name, f(d), f(d)))
            else: I('%s: 下穴φ%s trong PDF khớp lỗ đã vẽ' % (name, f(d)))
        if pil_known:
            for d, k in dr.items():
                if d in PILOT and d not in pil: W('%s: %d lỗ φ%s (= lỗ mồi %s theo bảng) trong khi PDF có 下穴φ%s: ghi chú tay thắng bảng, đối chiếu từng nhóm' % (name, k, f(d), '/'.join(PILOT[d]), '/'.join(f(x) for x in sorted(pil))))
        if len(mine) == 1 and len(mine[0]['codes']) == 1:   # trang chỉ có 1 mã: đếm được
            tot = defaultdict(int)
            for k, d in mine[0]['hole']: tot[d] += k
            for d, k in sorted(tot.items()):
                if d not in pil and dr.get(d, 0) != k: W('%s: PDF ghi tổng %d-φ%s, hình có %d lỗ φ%s (đếm lại từng ghi chú; lỗ bị gạch thì bỏ qua)' % (name, k, f(d), dr.get(d, 0), f(d)))
        for x in sorted(union([n['dev'] for n in mine])):
            if not (abs(Wd - x) < 0.05 or abs(Hd - x) < 0.05): W('%s: PDF ghi 展開 %s, phôi %s x %s' % (name, f(x), f(Wd), f(Hd)))
        if mine:
            mt, t = mat_of(name); lr = laser_r(mt, t) if mt and t else None
            pr = union([n['R'] for n in mine]); arcs = {round(Seg(e).r, 2) for c, e in its if c == 'cut' and e.dxftype() == 'ARC'}
            miss = sorted(x for x in pr if x not in arcs and x != lr); extra = sorted(x for x in arcs if x not in pr and x != lr)
            if miss: I('%s: R trong PDF mà hình không có cung R đó: %s (R ở hình chiếu khác thì bỏ qua)' % (name, ', '.join(f(x) for x in miss)))
            if extra: I('%s: cung R trong hình mà PDF không ghi: %s (R lấy từ DXF khách/hạ R thì bỏ qua)' % (name, ', '.join(f(x) for x in extra)))
        for c, a, bb in mydx:
            if bb and not ((abs(Wd - bb[0]) < 0.1 and abs(Hd - bb[1]) < 0.1) or (abs(Wd - bb[1]) < 0.1 and abs(Hd - bb[0]) < 0.1)):
                I('%s: khung DXF khách %s x %s khác phôi %s x %s (phôi uốn/DXF nhiều hình thì bình thường; đối chiếu tay)' % (name, f(bb[0]), f(bb[1]), f(Wd), f(Hd)))
    want = {d for n in pn for k, d in n['hole'] if d not in union([x['pilot'] for x in pn])}
    for d in sorted(want - drawn_all): W('NGUỒN: PDF ghi n-φ%s nhưng không hình nào vẽ lỗ φ%s (lỗ gạch/lỗ ren thì bỏ qua, còn lại là thiếu lỗ)' % (f(d), f(d)))

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('file'); ap.add_argument('--tpl', default='/mnt/project-files/knowledge/Context_Laser/Template.dxf')
    ap.add_argument('--template', action='store_true', help='bật so cấu trúc file với Template (mặc định tắt, chỉ kiểm hình dạng)')
    ap.add_argument('--mat', choices=['SS', 'SUS', 'AL', 'CU']); ap.add_argument('--t', type=float)
    ap.add_argument('--expect'); ap.add_argument('--order'); ap.add_argument('--mirror', action='append', default=[])
    ap.add_argument('--single'); ap.add_argument('--png')
    ap.add_argument('--slot', action='append', default=[], help='rãnh ghi chú NxM (tổng dài x rộng), lặp được; LỖI nếu DXF có rãnh mà không rãnh nào khớp')
    ap.add_argument('--src', help='thư mục đơn chứa PDF bản vẽ/依頼 và DXF khách (mặc định: thư mục của FILE); đối chiếu kỳ vọng từ nguồn')
    a = ap.parse_args()
    for sl in a.slot:
        m = re.fullmatch(r'(\d+(?:\.\d+)?)\s*[xX×*]\s*(\d+(?:\.\d+)?)', sl.strip())
        if m: SLOTS.append((float(m.group(1)), float(m.group(2))))
        else: ap.error('--slot %r: dùng dạng NxM, ví dụ 20x5' % sl)
    is_all = a.file.upper().endswith('_ALL.DXF')
    exp = {}
    if a.expect:
        for ln in open(a.expect, encoding='utf-8-sig'):
            r = [x.strip() for x in ln.split(',')]
