        if not hit: W('Cặp %s: %s không phải ảnh gương/xoay của %s, kiểm tay từng chi tiết (lỗ, kegaki, cánh)' % (m, B, A))
        elif any('gương' in x for x in hit): I('Cặp %s: %s là %s của %s' % (m, B, ' / '.join(hit), A))
